B.au4=new A.hd("bn_story_1","\u09b8\u0995\u09be\u09b2\u09c7\u09b0 \u099a\u09dc\u09c1\u0987 \u09aa\u09be\u0996\u09bf","bn","\u09aa\u09cd\u09b0\u09a4\u09bf\u09a6\u09bf\u09a8 \u09b8\u0995\u09be\u09b2\u09c7 \u098f\u0995\u099f\u09bf \u099b\u09cb\u099f\u09cd\u099f \u099a\u09dc\u09c1\u0987 \u09aa\u09be\u0996\u09bf \u09ac\u09be\u09b0\u09be\u09a8\u09cd\u09a6\u09be\u09b0 \u09b0\u09c7\u09b2\u09bf\u0982\u09df\u09c7 \u098f\u09b8\u09c7 \u09ac\u09b8\u09c7\u0964 \u09ae\u09bf\u09b7\u09cd\u099f\u09bf \u09b0\u09cb\u09a6\u09c7 \u09b8\u09c7 \u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u0997\u09be\u09a8 \u0997\u09be\u09df\u0964 \u09ac\u09be\u0997\u09be\u09a8\u09c7\u09b0 \u09ab\u09c1\u09b2\u0997\u09c1\u09b2\u09cb \u09af\u0996\u09a8 \u09ac\u09be\u09a4\u09be\u09b8\u09c7 \u09a6\u09cb\u09b2\u09c7, \u09aa\u09be\u0996\u09bf\u099f\u09bf \u09a1\u09be\u09a8\u09be \u09ae\u09c7\u09b2\u09c7 \u09b6\u09be\u09a8\u09cd\u09a4\u09bf\u09a4\u09c7 \u09ac\u09b8\u09c7 \u09a5\u09be\u0995\u09c7\u0964","nature")
