B.arV=new A.D(B.R,["Find the prominent single horn and gentle face of the rhinoceros grazing near the golden wetland.","\u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u099c\u09b2\u09be\u09b6\u09af\u09bc\u09f0 \u0995\u09be\u09b7\u09a4 \u0998\u09be\u0981\u09b9 \u0996\u09be\u0987 \u09a5\u0995\u09be \u0997\u0981\u09a1\u09bc\u099f\u09cb\u09f0 \u0989\u099c\u09cd\u099c\u09cd\u09ac\u09b2 \u098f\u0995\u09b6\u09bf\u0999 \u0986\u09f0\u09c1 \u09b6\u09be\u09a8\u09cd\u09a4 \u09ae\u09c1\u0996\u0996\u09a8 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0938\u0941\u0928\u0939\u0930\u0940 \u091d\u0940\u0932 \u0915\u0947 \u092a\u093e\u0938 \u0918\u093e\u0938 \u091a\u0930 \u0930\u0939\u0947 \u0917\u0948\u0902\u0921\u0947 \u0915\u093e \u092a\u094d\u0930\u0938\u093f\u0926\u094d\u0927 \u090f\u0915 \u0938\u0940\u0902\u0917 \u0914\u0930 \u0936\u093e\u0902\u0924 \u091a\u0947\u0939\u0930\u093e \u0926\u0947\u0916\u0947\u0902\u0964","\u099c\u09b2\u09be\u09ad\u09c2\u09ae\u09bf\u09b0 \u09aa\u09be\u09b6\u09c7 \u0998\u09be\u09b8 \u0996\u09be\u0993\u09af\u09bc\u09be \u0997\u09a3\u09cd\u09a1\u09be\u09b0\u09c7\u09b0 \u09ac\u09bf\u0996\u09cd\u09af\u09be\u09a4 \u098f\u0995\u099f\u09bf \u09b6\u09bf\u0982 \u098f\u09ac\u0982 \u09b6\u09be\u09a8\u09cd\u09a4 \u09ae\u09c1\u0996\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.ash=new A.D(B.R,["Notice the calm wetlands and distant wild buffaloes grazing under the evening sky.","\u09b8\u09a8\u09cd\u09a7\u09bf\u09af\u09bc\u09be\u09f0 \u0986\u0995\u09be\u09b6\u09f0 \u09a4\u09b2\u09a4 \u099a\u09f0\u09bf \u09a5\u0995\u09be \u09ac\u09a8\u09f0\u09c0\u09af\u09bc\u09be \u09ae\u0981\u09b9 \u0986\u09f0\u09c1 \u09b6\u09be\u09a8\u09cd\u09a4 \u099c\u09b2\u09be\u09b6\u09af\u09bc\u09f0 \u09a6\u09c3\u09b6\u09cd\u09af\u099f\u09cb \u099a\u09be\u0993\u0995\u0964","\u0936\u093e\u092e \u0915\u0947 \u0906\u0915\u093e\u0936 \u0915\u0947 \u0928\u0940\u091a\u0947 \u0936\u093e\u0902\u0924 \u091c\u0932 \u0914\u0930 \u0926\u0942\u0930 \u091a\u0930\u0924\u0940 \u091c\u0902\u0917\u0932\u0940 \u092d\u0948\u0902\u0938\u094b\u0902 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u09b8\u09a8\u09cd\u09a7\u09cd\u09af\u09be\u09b0 \u0986\u0995\u09be\u09b6\u09c7\u09b0 \u09a8\u09bf\u099a\u09c7 \u09b6\u09be\u09a8\u09cd\u09a4 \u099c\u09b2\u09be\u09ad\u09c2\u09ae\u09bf \u098f\u09ac\u0982 \u09a6\u09c2\u09b0\u09c7 \u099a\u09b0\u09c7 \u09ac\u09c7\u09a1\u09bc\u09be\u09a8\u09cb \u09ac\u09c1\u09a8\u09cb \u09ae\u09cb\u09b7\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.as0=new A.D(B.R,["Look for the warm golden sunset glowing over the misty green hills and quiet riverbanks.","\u0995\u09c1\u0981\u09f1\u09b2\u09c0\u09ad\u09f0\u09be \u09aa\u09be\u09b9\u09be\u09f0 \u0986\u09f0\u09c1 \u09a8\u09a6\u09c0\u09f0 \u09aa\u09be\u09f0\u09a4 \u09ac\u09bf\u09af\u09bc\u09aa\u09bf \u09aa\u09f0\u09be \u0986\u09ac\u09c7\u09b2\u09bf\u09f0 \u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u09f0\u2019\u09a6\u099c\u09be\u0995 \u099a\u09be\u0993\u0995\u0964","\u0927\u0941\u0902\u0927\u0932\u0940 \u092a\u0939\u093e\u0921\u093c\u093f\u092f\u094b\u0902 \u0914\u0930 \u0928\u0926\u0940 \u0915\u093f\u0928\u093e\u0930\u0947 \u091a\u092e\u0915\u0924\u0940 \u0936\u093e\u092e \u0915\u0940 \u0938\u0941\u0928\u0939\u0930\u0940 \u0927\u0942\u092a \u0926\u0947\u0916\u0947\u0902\u0964","\u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u099a\u09c2\u09a1\u09bc\u09be \u0993 \u09a8\u09a6\u09c0\u09b0 \u09a4\u09c0\u09b0\u09c7 \u099b\u09a1\u09bc\u09bf\u09af\u09bc\u09c7 \u09aa\u09a1\u09bc\u09be \u09b8\u09a8\u09cd\u09a7\u09cd\u09af\u09be\u09b0 \u09b8\u09cb\u09a8\u09be\u09b2\u09c0 \u09b0\u09cb\u09a6\u09cd\u09a6\u09c1\u09b0 \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asE=new A.D(B.R,["Find the sturdy hind legs and thick protective skin of the rhinoceros planted in the grass.","\u0998\u09be\u0981\u09b9\u09a8\u09bf\u09a4 \u09a6\u09c3\u09a2\u09bc\u09ad\u09be\u09f1\u09c7 \u09a5\u09bf\u09af\u09bc \u09b9\u09c8 \u09a5\u0995\u09be \u0997\u0981\u09a1\u09bc\u099f\u09cb\u09f0 \u09aa\u09bf\u099b\u09ab\u09be\u09b2\u09f0 \u09ad\u09f0\u09bf \u0986\u09f0\u09c1 \u09a1\u09be\u09a0 \u099a\u09be\u09ae\u09f0\u09be\u0996\u09bf\u09a8\u09bf \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0918\u093e\u0938 \u092e\u0947\u0902 \u092e\u091c\u092c\u0942\u0924\u0940 \u0938\u0947 \u091c\u092e\u0947 \u0917\u0948\u0902\u0921\u0947 \u0915\u0947 \u092a\u093f\u091b\u0932\u0947 \u092a\u0948\u0930 \u0914\u0930 \u0909\u0938\u0915\u0940 \u092d\u093e\u0930\u0940 \u0938\u0941\u0930\u0915\u094d\u0937\u093e\u0924\u094d\u092e\u0915 \u0916\u093e\u0932 \u0916\u094b\u091c\u0947\u0902\u0964","\u0998\u09be\u09b8\u09c7\u09b0 \u0989\u09aa\u09b0 \u09ae\u099c\u09ac\u09c1\u09a4\u09ad\u09be\u09ac\u09c7 \u09a6\u09be\u0981\u09a1\u09bc\u09bf\u09af\u09bc\u09c7 \u09a5\u09be\u0995\u09be \u0997\u09a3\u09cd\u09a1\u09be\u09b0\u09c7\u09b0 \u09aa\u09c7\u099b\u09a8\u09c7\u09b0 \u09aa\u09be \u0993 \u099a\u0993\u09a1\u09bc\u09be \u099a\u09be\u09ae\u09a1\u09bc\u09be\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.as8=new A.D(B.R,["Look for the iconic curved horn and snout of the rhino as it feeds on fresh green shoots.","\u09b8\u09a4\u09c7\u099c \u09b8\u09c7\u0989\u099c\u09c0\u09af\u09bc\u09be \u0998\u09be\u0981\u09b9 \u0996\u09be\u0987 \u09a5\u0995\u09be \u0997\u0981\u09a1\u09bc\u099f\u09cb\u09f0 \u09a7\u09c1\u09a8\u09c0\u09af\u09bc\u09be \u09b6\u09bf\u0982 \u0986\u09f0\u09c1 \u09ae\u09c1\u0996\u09f0 \u0985\u0982\u09b6\u099f\u09cb \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0924\u093e\u091c\u0940 \u0939\u0930\u0940 \u0918\u093e\u0938 \u0916\u093e \u0930\u0939\u0947 \u0917\u0948\u0902\u0921\u0947 \u0915\u093e \u0916\u0942\u092c\u0938\u0942\u0930\u0924 \u092e\u0941\u0921\u093c\u093e \u0939\u0941\u0906 \u0938\u0940\u0902\u0917 \u0914\u0930 \u091a\u0947\u0939\u0930\u093e \u0916\u094b\u091c\u0947\u0902\u0964","\u09a4\u09be\u099c\u09be \u09b8\u09ac\u09c1\u099c \u0998\u09be\u09b8 \u0996\u09be\u0993\u09af\u09bc\u09be \u0997\u09a3\u09cd\u09a1\u09be\u09b0\u09c7\u09b0 \u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u09ac\u09be\u0981\u0995\u09be\u09a8\u09cb \u09b6\u09bf\u0982 \u0993 \u09ae\u09c1\u0996\u099f\u09bf \u0996\u09c1\u0981\u099c\u09c1\u09a8\u0964"],t.w)
B.arO=new A.D(B.R,["Notice the soft blue mountain ridges and the peaceful shallow water pools.","\u09a6\u09c2\u09f0\u09a3\u09bf\u09f0 \u09a8\u09c0\u09b2\u09be \u09aa\u09be\u09b9\u09be\u09f0\u09f0 \u09b6\u09be\u09f0\u09c0 \u0986\u09f0\u09c1 \u09b6\u09be\u09a8\u09cd\u09a4 \u09aa\u09be\u09a8\u09c0\u09f0 \u09b8\u09f0\u09c1 \u09ac\u09bf\u09b2\u0996\u09a8 \u099a\u09be\u0993\u0995\u0964","\u0926\u0942\u0930 \u0915\u0940 \u0928\u0940\u0932\u0940 \u092a\u0939\u093e\u0921\u093c\u093f\u092f\u094b\u0902 \u0914\u0930 \u0936\u093e\u0902\u0924 \u092a\u093e\u0928\u0940 \u0915\u0947 \u091b\u094b\u091f\u0947 \u0924\u093e\u0932\u094b\u0902 \u0935\u093e\u0932\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u0926\u0947\u0916\u0947\u0902\u0964","\u09a6\u09c2\u09b0\u09c7\u09b0 \u09a8\u09c0\u09b2 \u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u09b0\u09c7\u0996\u09be \u098f\u09ac\u0982 \u09b6\u09be\u09a8\u09cd\u09a4 \u099c\u09b2\u09c7\u09b0 \u0985\u0997\u09ad\u09c0\u09b0 \u099c\u09b2\u09be\u09b6\u09af\u09bc\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asj=new A.D(B.R,["Look for the wild water buffaloes grazing together peacefully in the wide marshes.","\u09ac\u09b9\u09b2 \u099c\u09b2\u09be\u09b6\u09af\u09bc\u09a4 \u098f\u0995\u09c7\u09b2\u0997\u09c7 \u09b6\u09be\u09a8\u09cd\u09a4\u09ad\u09be\u09f1\u09c7 \u099a\u09f0\u09bf \u09a5\u0995\u09be \u09ac\u09a8\u09f0\u09c0\u09af\u09bc\u09be \u09ae\u0981\u09b9\u09f0 \u099c\u09be\u0995\u099f\u09cb \u099a\u09be\u0993\u0995\u0964","\u0935\u093f\u0938\u094d\u0924\u0943\u0924 \u0926\u0932\u0926\u0932 \u092e\u0947\u0902 \u090f\u0915 \u0938\u093e\u0925 \u0936\u093e\u0902\u0924\u093f \u0938\u0947 \u091a\u0930\u0924\u0940 \u091c\u0902\u0917\u0932\u0940 \u092d\u0948\u0902\u0938\u094b\u0902 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u09ac\u09bf\u09b6\u09be\u09b2 \u099c\u09b2\u09be\u09ad\u09c2\u09ae\u09bf\u09a4\u09c7 \u098f\u0995\u09b8\u09be\u09a5\u09c7 \u099a\u09b0\u09c7 \u09ac\u09c7\u09a1\u09bc\u09be\u09a8\u09cb \u09ac\u09c1\u09a8\u09cb \u09ae\u09cb\u09b7\u09c7\u09b0 \u09aa\u09be\u09b2\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asF=new A.D(B.R,["Find the radiant sunset sky casting a warm golden light over the grasslands.","\u0998\u09be\u0981\u09b9\u09a8\u09bf\u09a4 \u09ac\u09bf\u09af\u09bc\u09aa\u09bf \u09aa\u09f0\u09be \u09b8\u09c2\u09f0\u09cd\u09af\u09be\u09b8\u09cd\u09a4\u09f0 \u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u0986\u0995\u09be\u09b6 \u0986\u09f0\u09c1 \u09ae\u09c3\u09a6\u09c1 \u09aa\u09cb\u09b9\u09f0 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0918\u093e\u0938 \u0915\u0947 \u092e\u0948\u0926\u093e\u0928 \u092a\u0930 \u0938\u0941\u0928\u0939\u0930\u0940 \u0915\u093f\u0930\u0923\u0947\u0902 \u092c\u093f\u0916\u0947\u0930\u0924\u093e \u0921\u0942\u092c\u0924\u0947 \u0938\u0942\u0930\u091c \u0915\u093e \u0938\u0941\u0902\u0926\u0930 \u0906\u0915\u093e\u0936 \u0926\u0947\u0916\u0947\u0902\u0964","\u0998\u09be\u09b8\u09c7\u09b0 \u09aa\u09cd\u09b0\u09be\u09a8\u09cd\u09a4\u09b0\u09c7 \u09b8\u09cb\u09a8\u09be\u09b2\u09c0 \u0986\u09b2\u09cb \u099b\u09a1\u09bc\u09be\u09a8\u09cb \u09b8\u09c2\u09b0\u09cd\u09af\u09be\u09b8\u09cd\u09a4\u09c7\u09b0 \u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u0986\u0995\u09be\u09b6\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asq=new A.D(B.R,["Look for the back legs and short tail of the rhino surrounded by lush wetland reeds.","\u099c\u09b2\u09be\u09b6\u09af\u09bc\u09f0 \u0993\u0996 \u09a8\u09b2\u09c0-\u0996\u09be\u0997\u09f0\u09bf\u09f0 \u09ae\u09be\u099c\u09a4 \u09a5\u0995\u09be \u0997\u0981\u09a1\u09bc\u099f\u09cb\u09f0 \u09aa\u09bf\u099b\u09ab\u09be\u09b2 \u0986\u09f0\u09c1 \u09a8\u09c7\u099c\u09a1\u09be\u09b2 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u090a\u0902\u091a\u0940 \u0918\u093e\u0938 \u0914\u0930 \u0938\u0930\u0915\u0902\u0921\u094b\u0902 \u0915\u0947 \u092c\u0940\u091a \u0917\u0948\u0902\u0921\u0947 \u0915\u0947 \u092a\u093f\u091b\u0932\u0947 \u092a\u0948\u0930 \u0914\u0930 \u091b\u094b\u091f\u0940 \u092a\u0942\u0902\u091b \u0926\u0947\u0916\u0947\u0902\u0964","\u0989\u0981\u099a\u09c1 \u0998\u09be\u09b8\u09c7\u09b0 \u09ae\u09be\u099d\u09c7 \u0997\u09a3\u09cd\u09a1\u09be\u09b0\u09c7\u09b0 \u09aa\u09c7\u099b\u09a8\u09c7\u09b0 \u09aa\u09be \u0993 \u099b\u09cb\u099f \u09b2\u09c7\u099c\u09c7\u09b0 \u0985\u0982\u09b6\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asG=new A.D(B.R,["Notice the massive armored shoulder and textured gray back of the rhinoceros.","\u0997\u0981\u09a1\u09bc\u099f\u09cb\u09f0 \u09b6\u0995\u09cd\u09a4\u09bf\u09b6\u09be\u09b2\u09c0 \u09a1\u09be\u09a0 \u0995\u09be\u09a8\u09cd\u09a7 \u0986\u09f0\u09c1 \u09ac\u09b2\u09bf\u09b7\u09cd\u09a0 \u09aa\u09bf\u09a0\u09bf\u09f0 \u0985\u0982\u09b6\u099f\u09cb \u09b2\u0995\u09cd\u09b7\u09cd\u09af \u0995\u09f0\u0995\u0964","\u0917\u0948\u0902\u0921\u0947 \u0915\u0947 \u092d\u093e\u0930\u0940 \u0915\u0902\u0927\u0947 \u0914\u0930 \u0915\u0935\u091a \u091c\u0948\u0938\u0940 \u092e\u091c\u092c\u0942\u0924 \u0938\u094d\u0932\u0947\u091f\u0940 \u092a\u0940\u0920 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u0997\u09a3\u09cd\u09a1\u09be\u09b0\u09c7\u09b0 \u09ac\u09bf\u09b6\u09be\u09b2 \u0995\u09be\u0981\u09a7 \u098f\u09ac\u0982 \u09b6\u0995\u09cd\u09a4 \u09ac\u09b0\u09cd\u09ae\u09c7\u09b0 \u09ae\u09a4\u09cb \u09aa\u09bf\u09a0\u09c7\u09b0 \u0985\u0982\u09b6\u099f\u09bf \u09b2\u0995\u09cd\u09b7\u09cd\u09af \u0995\u09b0\u09c1\u09a8\u0964"],t.w)
B.asc=new A.D(B.R,["Find the magnificent curved horn, gentle eyes, and snout of the rhino grazing on green grass.","\u0995\u09cb\u09ae\u09b2 \u09b8\u09c7\u0989\u099c\u09c0\u09af\u09bc\u09be \u0998\u09be\u0981\u09b9 \u0996\u09be\u0987 \u09a5\u0995\u09be \u0997\u0981\u09a1\u09bc\u099f\u09cb\u09f0 \u09b8\u09c1\u09a8\u09cd\u09a6\u09f0 \u098f\u0995\u09b6\u09bf\u0999, \u099a\u0995\u09c1\u099c\u09c1\u09f0\u09bf \u0986\u09f0\u09c1 \u09ae\u09c1\u0996\u0996\u09a8 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0939\u0930\u0940 \u0918\u093e\u0938 \u091a\u0930\u0924\u0947 \u0917\u0948\u0902\u0921\u0947 \u0915\u093e \u0930\u093e\u091c\u0938\u0940 \u0938\u0940\u0902\u0917, \u0936\u093e\u0902\u0924 \u0906\u0902\u0916\u0947\u0902 \u0914\u0930 \u0909\u0938\u0915\u093e \u092e\u0941\u0902\u0939 \u0916\u094b\u091c\u0947\u0902\u0964","\u09b8\u09ac\u09c1\u099c \u0998\u09be\u09b8 \u0996\u09be\u0993\u09af\u09bc\u09be \u0997\u09a3\u09cd\u09a1\u09be\u09b0\u09c7\u09b0 \u0985\u09aa\u09c2\u09b0\u09cd\u09ac \u09b6\u09bf\u0982, \u09b6\u09be\u09a8\u09cd\u09a4 \u099a\u09cb\u0996 \u0993 \u09ae\u09c1\u0996\u099f\u09bf \u0996\u09c1\u0981\u099c\u09c1\u09a8\u0964"],t.w)
B.atc=new A.D(B.l3,[B.as9,B.arV,B.ash,B.as0,B.asE,B.as8,B.arO,B.asj,B.asF,B.asq,B.asG,B.asc],t.vb)
B.asB=new A.D(B.R,["Notice the snow-capped Himalayan mountain peaks rising above the golden-roofed buildings of the monastery.","\u09ae\u09a0\u09f0 \u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u099a\u09be\u09b2\u09f0 \u0993\u09aa\u09f0\u09a4 \u099c\u09bf\u09b2\u09bf\u0995\u09bf \u09a5\u0995\u09be \u09ac\u09f0\u09ab\u09c7\u09f0\u09c7 \u0986\u09ac\u09c3\u09a4 \u09b9\u09bf\u09ae\u09be\u09b2\u09af\u09bc\u09f0 \u09b6\u09c3\u0982\u0997\u09ac\u09cb\u09f0 \u099a\u09be\u0993\u0995\u0964","\u092e\u0920 \u0915\u0940 \u0938\u0941\u0928\u0939\u0930\u0940 \u091b\u0924\u094b\u0902 \u0915\u0947 \u092a\u0940\u091b\u0947 \u091a\u092e\u0915\u0924\u0940 \u092c\u0930\u094d\u092b \u0938\u0947 \u0922\u0915\u0940 \u0939\u093f\u092e\u093e\u0932\u092f \u0915\u0940 \u092a\u0930\u094d\u0935\u0924 \u091a\u094b\u091f\u093f\u092f\u093e\u0902 \u0926\u0947\u0916\u0947\u0902\u0964","\u09ae\u09a0\u09c7\u09b0 \u09b8\u09cb\u09a8\u09be\u09b2\u09c0 \u099b\u09be\u09a6\u09c7\u09b0 \u09aa\u09c7\u099b\u09a8\u09c7 \u09a6\u09c3\u09b6\u09cd\u09af\u09ae\u09be\u09a8 \u09ac\u09b0\u09ab\u09c7 \u09a2\u09be\u0995\u09be \u09b9\u09bf\u09ae\u09be\u09b2\u09af\u09bc\u09c7\u09b0 \u09aa\u09b0\u09cd\u09ac\u09a4\u09ae\u09be\u09b2\u09be \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.arN=new A.D(B.R,["Look for the sacred central prayer shrine and colorful Buddhist prayer flags fluttering along the hill trail.","\u09aa\u09be\u09b9\u09be\u09f0\u09c0\u09af\u09bc\u09be \u09ac\u09be\u099f\u09a4 \u0989\u09f0\u09bf \u09a5\u0995\u09be \u09f0\u0999\u09c0\u09a8 \u09ac\u09cc\u09a6\u09cd\u09a7 \u09aa\u09cd\u09f0\u09be\u09f0\u09cd\u09a5\u09a8\u09be\u09f0 \u09aa\u09a4\u09be\u0995\u09be \u0986\u09f0\u09c1 \u09ae\u09c2\u09b2 \u09ae\u09a8\u09cd\u09a6\u09bf\u09f0\u099f\u09cb \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u092a\u0939\u093e\u0921\u093c\u0940 \u0930\u093e\u0938\u094d\u0924\u0947 \u092a\u0930 \u0932\u0939\u0930\u093e\u0924\u0940 \u0930\u0902\u0917-\u092c\u093f\u0930\u0902\u0917\u0940 \u092c\u094c\u0926\u094d\u0927 \u092a\u094d\u0930\u093e\u0930\u094d\u0925\u0928\u093e \u092a\u0924\u093e\u0915\u093e\u090f\u0902 \u0914\u0930 \u092e\u0941\u0916\u094d\u092f \u092e\u0902\u0926\u093f\u0930 \u092d\u0935\u0928 \u0926\u0947\u0916\u0947\u0902\u0964","\u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u09aa\u09a5\u09c7 \u0989\u09a1\u09bc\u09a4\u09c7 \u09a5\u09be\u0995\u09be \u09b0\u0999\u09bf\u09a8 \u09ac\u09cc\u09a6\u09cd\u09a7 \u09aa\u09cd\u09b0\u09be\u09b0\u09cd\u09a5\u09a8\u09be\u09b0 \u09aa\u09a4\u09be\u0995\u09be \u098f\u09ac\u0982 \u09ae\u09c2\u09b2 \u09ae\u09a8\u09cd\u09a6\u09bf\u09b0\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asN=new A.D(B.R,["Find the sharp, glistening snow peaks standing tall against the deep blue mountain sky.","\u09a8\u09c0\u09b2\u09be \u0986\u0995\u09be\u09b6\u09f0 \u09ac\u09c1\u0995\u09c1\u09a4 \u099c\u09bf\u09b2\u09bf\u0995\u09bf \u09a5\u0995\u09be \u09ac\u09f0\u09ab\u09f0 \u09b6\u09c1\u09ad\u09cd\u09f0 \u09aa\u09f0\u09cd\u09ac\u09a4\u09ae\u09be\u09b2\u09be\u09f0 \u09b6\u09c3\u0982\u0997\u09ac\u09cb\u09f0 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0917\u0939\u0930\u0947 \u0928\u0940\u0932\u0947 \u0906\u0915\u093e\u0936 \u0915\u0947 \u0938\u093e\u092e\u0928\u0947 \u0916\u0921\u093c\u0940 \u0924\u0940\u0916\u0940 \u092c\u0930\u094d\u092b \u0938\u0947 \u0922\u0915\u0940 \u0938\u092b\u0947\u0926 \u092a\u0930\u094d\u0935\u0924 \u091a\u094b\u091f\u093f\u092f\u093e\u0902 \u0916\u094b\u091c\u0947\u0902\u0964","\u09a8\u09c0\u09b2 \u0986\u0995\u09be\u09b6\u09c7\u09b0 \u09ac\u09c1\u0995\u09c7 \u09ae\u09be\u09a5\u09be \u09a4\u09c1\u09b2\u09c7 \u09a6\u09be\u0981\u09a1\u09bc\u09be\u09a8\u09cb \u09b6\u09c1\u09ad\u09cd\u09b0 \u09ac\u09b0\u09ab\u09be\u09ac\u09c3\u09a4 \u09aa\u09b0\u09cd\u09ac\u09a4\u09c7\u09b0 \u099a\u09c2\u09a1\u09bc\u09be\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.as_=new A.D(B.R,["Notice the majestic high-altitude snowy crests touched by soft wandering clouds.","\u09ac\u0997\u09be \u09a1\u09be\u09f1\u09f0\u09c7 \u099a\u09c1\u0987 \u09af\u09cb\u09f1\u09be \u0993\u0996 \u09ac\u09f0\u09ab\u09be\u09ac\u09c3\u09a4 \u09aa\u09f0\u09cd\u09ac\u09a4\u09f0 \u09b6\u09bf\u0996\u09f0\u09ac\u09cb\u09f0 \u09b2\u0995\u09cd\u09b7\u09cd\u09af \u0995\u09f0\u0995\u0964","\u0939\u0932\u094d\u0915\u0947 \u092c\u093e\u0926\u0932\u094b\u0902 \u0938\u0947 \u0918\u093f\u0930\u0940 \u0939\u093f\u092e\u093e\u0932\u092f \u0915\u0940 \u090a\u0902\u091a\u0940 \u092c\u0930\u094d\u092b\u0940\u0932\u0940 \u091a\u094b\u091f\u093f\u092f\u094b\u0902 \u0935\u093e\u0932\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u0926\u0947\u0916\u0947\u0902\u0964","\u09b9\u09be\u09b2\u0995\u09be \u09ae\u09c7\u0998\u09c7\u09b0 \u099b\u09cb\u0981\u09af\u09bc\u09be \u09aa\u09be\u0993\u09af\u09bc\u09be \u09ac\u09b0\u09ab\u09c7 \u09ae\u09cb\u09a1\u09bc\u09be \u09b9\u09bf\u09ae\u09be\u09b2\u09af\u09bc\u09c7\u09b0 \u09b8\u09c1\u0989\u099a\u09cd\u099a \u09b6\u09c3\u0999\u09cd\u0997\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asO=new A.D(B.R,["Look for the tiered whitewashed buildings with bright yellow roofs perched on the green slope.","\u09b8\u09c7\u0989\u099c\u09c0\u09af\u09bc\u09be \u09aa\u09be\u09b9\u09be\u09f0\u09f0 \u0997\u09be\u09a4 \u09a5\u0995\u09be \u09ac\u0997\u09be \u09a6\u09c7\u09f1\u09be\u09b2 \u0986\u09f0\u09c1 \u09b9\u09be\u09b2\u09a7\u09c0\u09af\u09bc\u09be \u099a\u09be\u09b2\u09f0 \u09ac\u09cc\u09a6\u09cd\u09a7 \u0986\u09b6\u09cd\u09f0\u09ae\u09ac\u09cb\u09f0 \u099a\u09be\u0993\u0995\u0964","\u092a\u0939\u093e\u0921\u093c\u0940 \u0922\u0932\u093e\u0928 \u092a\u0930 \u092c\u0928\u0940 \u0938\u092b\u0947\u0926 \u0926\u0940\u0935\u093e\u0930\u094b\u0902 \u0914\u0930 \u092a\u0940\u0932\u0940 \u091b\u0924\u094b\u0902 \u0935\u093e\u0932\u0940 \u092c\u094c\u0926\u094d\u0927 \u092d\u093f\u0915\u094d\u0937\u0941\u0913\u0902 \u0915\u0940 \u0915\u0941\u091f\u093f\u092f\u093e\u0902 \u0926\u0947\u0916\u0947\u0902\u0964","\u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u0997\u09be\u09af\u09bc\u09c7 \u09a7\u09be\u09aa\u09c7 \u09a7\u09be\u09aa\u09c7 \u09b8\u09be\u099c\u09be\u09a8\u09cb \u09b8\u09be\u09a6\u09be \u09a6\u09c7\u09af\u09bc\u09be\u09b2 \u0993 \u09b9\u09b2\u09c1\u09a6 \u099b\u09be\u09a6\u09c7\u09b0 \u09ae\u09a0\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asa=new A.D(B.R,["Find the grand central monastery assembly hall and the strings of vibrant prayer flags.","\u09ae\u09a0\u09f0 \u09ae\u09c2\u09b2 \u09aa\u09cd\u09f0\u09be\u09f0\u09cd\u09a5\u09a8\u09be \u09ad\u09f1\u09a8 \u0986\u09f0\u09c1 \u09ac\u09a4\u09be\u09b9\u09a4 \u0989\u09f0\u09bf \u09a5\u0995\u09be \u09f0\u0999\u09c0\u09a8 \u09aa\u09a4\u09be\u0995\u09be\u09f0 \u09b6\u09be\u09f0\u09c0\u099f\u09cb \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u092e\u0920 \u0915\u093e \u092e\u0941\u0916\u094d\u092f \u092a\u094d\u0930\u093e\u0930\u094d\u0925\u0928\u093e \u092d\u0935\u0928 \u0914\u0930 \u0939\u0935\u093e \u092e\u0947\u0902 \u0932\u0939\u0930\u093e\u0924\u0940 \u0930\u0902\u0917\u0940\u0928 \u092a\u0924\u093e\u0915\u093e\u0913\u0902 \u0915\u0940 \u0932\u0921\u093c\u093f\u092f\u093e\u0902 \u0916\u094b\u091c\u0947\u0902\u0964","\u09ae\u09a0\u09c7\u09b0 \u09ae\u09c2\u09b2 \u09aa\u09cd\u09b0\u09be\u09b0\u09cd\u09a5\u09a8\u09be \u09ad\u09ac\u09a8 \u098f\u09ac\u0982 \u09ac\u09be\u09a4\u09be\u09b8\u09c7 \u09a6\u09c1\u09b2\u09a4\u09c7 \u09a5\u09be\u0995\u09be \u09b0\u0999\u09bf\u09a8 \u09aa\u09a4\u09be\u0995\u09be\u09b0 \u09ae\u09be\u09b2\u09be\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.arX=new A.D(B.R,["Notice the jagged snowy mountain ridge rising majestically above the forested valley.","\u09ac\u09a8\u09a8\u09bf\u09f0\u09c7 \u09ad\u09f0\u09be \u0989\u09aa\u09a4\u09cd\u09af\u0995\u09be\u09f0 \u0993\u09aa\u09f0\u09a4 \u0989\u09a0\u09bf \u0985\u09b9\u09be \u09a4\u09c0\u0995\u09cd\u09b7\u09cd\u09a3 \u09ac\u09f0\u09ab\u09f0 \u09aa\u09be\u09b9\u09be\u09f0\u09f0 \u09b6\u09bf\u0996\u09f0\u09ac\u09cb\u09f0 \u099a\u09be\u0993\u0995\u0964","\u091c\u0902\u0917\u0932\u094b\u0902 \u0938\u0947 \u092d\u0930\u0940 \u0918\u093e\u091f\u0940 \u0915\u0947 \u090a\u092a\u0930 \u0909\u0920\u0924\u0940 \u092c\u0930\u094d\u092b\u0940\u0932\u0940 \u092a\u0939\u093e\u0921\u093c\u0940 \u091a\u094b\u091f\u093f\u092f\u094b\u0902 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u09b8\u09ac\u09c1\u099c \u0989\u09aa\u09a4\u09cd\u09af\u0995\u09be\u09b0 \u0993\u09aa\u09b0 \u099c\u09c7\u0997\u09c7 \u09a5\u09be\u0995\u09be \u0996\u09be\u0981\u099c\u0995\u09be\u099f\u09be \u09ac\u09b0\u09ab\u09c7\u09b0 \u09aa\u09b0\u09cd\u09ac\u09a4\u099a\u09c2\u09a1\u09bc\u09be \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asx=new A.D(B.R,["Find the towering white summit of the Himalayas glistening brilliantly in the sunshine.","\u09f0\u2019\u09a6\u09a4 \u099c\u09bf\u09b2\u09bf\u0995\u09bf \u09a5\u0995\u09be \u09b9\u09bf\u09ae\u09be\u09b2\u09af\u09bc\u09f0 \u09b8\u09f0\u09cd\u09ac\u09cb\u099a\u09cd\u099a \u09ac\u09f0\u09ab\u09be\u09ac\u09c3\u09a4 \u09b6\u09c1\u09ad\u09cd\u09f0 \u09b6\u09bf\u0996\u09f0\u099f\u09cb \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0927\u0942\u092a \u092e\u0947\u0902 \u091a\u092e\u0915\u0924\u0940 \u0939\u093f\u092e\u093e\u0932\u092f \u0915\u0940 \u0938\u092c\u0938\u0947 \u090a\u0902\u091a\u0940 \u092c\u0930\u094d\u092b \u0938\u0947 \u0922\u0915\u0940 \u0935\u093f\u0936\u093e\u0932 \u091a\u094b\u091f\u0940 \u0916\u094b\u091c\u0947\u0902\u0964","\u09b0\u09cb\u09a6\u09c7 \u099d\u09bf\u0995\u09ae\u09bf\u0995 \u0995\u09b0\u09a4\u09c7 \u09a5\u09be\u0995\u09be \u09b9\u09bf\u09ae\u09be\u09b2\u09af\u09bc\u09c7\u09b0 \u09b8\u09b0\u09cd\u09ac\u09cb\u099a\u09cd\u099a \u09b6\u09c1\u09ad\u09cd\u09b0 \u09a4\u09c1\u09b7\u09be\u09b0\u09b6\u09c3\u0999\u09cd\u0997\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asf=new A.D(B.R,["Look for the serene alpine ridges fading into the clear blue morning sky.","\u09a8\u09bf\u09f0\u09cd\u09ae\u09b2 \u09aa\u09c1\u09f1\u09be\u09f0 \u09a8\u09c0\u09b2\u09be \u0986\u0995\u09be\u09b6\u09f0 \u09ac\u09c1\u0995\u09c1\u09a4 \u09ae\u09bf\u09b2\u09bf \u09af\u09cb\u09f1\u09be \u0993\u0996 \u09aa\u09be\u09b9\u09be\u09f0\u09f0 \u09a2\u09be\u09b2\u09ac\u09cb\u09f0 \u099a\u09be\u0993\u0995\u0964","\u0938\u093e\u092b \u0928\u0940\u0932\u0947 \u0906\u0938\u092e\u093e\u0928 \u092e\u0947\u0902 \u092e\u093f\u0932\u0924\u0940 \u0939\u0941\u0908 \u0926\u0942\u0930 \u0915\u0940 \u0936\u093e\u0902\u0924 \u092a\u0939\u093e\u0921\u093c\u0940 \u091a\u094b\u091f\u093f\u092f\u093e\u0902 \u0926\u0947\u0916\u0947\u0902\u0964","\u09a8\u09bf\u09b0\u09cd\u09ae\u09b2 \u09a8\u09c0\u09b2 \u0986\u0995\u09be\u09b6\u09c7\u09b0 \u0995\u09cb\u09b2\u09c7 \u09ae\u09bf\u09b2\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u0993\u09af\u09bc\u09be \u09a6\u09c2\u09b0\u09c7\u09b0 \u09b6\u09be\u09a8\u09cd\u09a4 \u09b6\u09c8\u09b2\u09b6\u09bf\u09b0\u09be \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asH=new A.D(B.R,["Look for the rows of traditional white monastic buildings with bright yellow rooftops.","\u09b9\u09be\u09b2\u09a7\u09c0\u09af\u09bc\u09be \u099a\u09be\u09b2 \u0986\u09f0\u09c1 \u09ac\u0997\u09be \u09a6\u09c7\u09f1\u09be\u09b2\u09f0 \u0990\u09a4\u09bf\u09b9\u09cd\u09af\u09ae\u09a3\u09cd\u09a1\u09bf\u09a4 \u09ac\u09cc\u09a6\u09cd\u09a7 \u0997\u09c3\u09b9\u09ac\u09cb\u09f0\u09f0 \u09b6\u09be\u09f0\u09c0\u099f\u09cb \u099a\u09be\u0993\u0995\u0964","\u091a\u092e\u0915\u0940\u0932\u0940 \u092a\u0940\u0932\u0940 \u091b\u0924\u094b\u0902 \u0914\u0930 \u0938\u092b\u0947\u0926 \u0926\u0940\u0935\u093e\u0930\u094b\u0902 \u0935\u093e\u0932\u0940 \u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u0907\u092e\u093e\u0930\u0924\u094b\u0902 \u0915\u0940 \u0915\u0924\u093e\u0930 \u0926\u0947\u0916\u0947\u0902\u0964","\u0989\u099c\u09cd\u099c\u09cd\u09ac\u09b2 \u09b9\u09b2\u09c1\u09a6 \u099b\u09be\u09a6 \u0993 \u09b8\u09be\u09a6\u09be \u09a6\u09c7\u09af\u09bc\u09be\u09b2\u09c7\u09b0 \u0990\u09a4\u09bf\u09b9\u09cd\u09af\u09ac\u09be\u09b9\u09c0 \u09ae\u09a0\u09c7\u09b0 \u09b8\u09be\u09b0\u09bf\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asd=new A.D(B.R,["Find the grand historic temple hall with its terracotta-tiled roof and carved wooden windows.","\u0990\u09a4\u09bf\u09b9\u09be\u09b8\u09bf\u0995 \u09ae\u09c2\u09b2 \u09ae\u09a8\u09cd\u09a6\u09bf\u09f0\u09f0 \u099a\u09be\u09b2 \u0986\u09f0\u09c1 \u0995\u09be\u09a0\u09f0 \u09a8\u0995\u09cd\u09b8\u09be \u0995\u099f\u09be \u0996\u09bf\u09f0\u09bf\u0995\u09c0\u09ac\u09cb\u09f0 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0938\u0941\u0902\u0926\u0930 \u0928\u0915\u094d\u0915\u093e\u0936\u0940\u0926\u093e\u0930 \u0916\u093f\u0921\u093c\u0915\u093f\u092f\u094b\u0902 \u0914\u0930 \u0932\u093e\u0932 \u091b\u0924 \u0935\u093e\u0932\u093e \u0910\u0924\u093f\u0939\u093e\u0938\u093f\u0915 \u092e\u0941\u0916\u094d\u092f \u092e\u0902\u0926\u093f\u0930 \u0916\u094b\u091c\u0947\u0902\u0964","\u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u0995\u09be\u09b0\u09c1\u0995\u09be\u099c \u0995\u09b0\u09be \u099c\u09be\u09a8\u09be\u09b2\u09be \u0993 \u09b2\u09be\u09b2 \u099b\u09be\u09a6\u09c7\u09b0 \u0990\u09a4\u09bf\u09b9\u09be\u09b8\u09bf\u0995 \u09ae\u09c2\u09b2 \u09ae\u09a8\u09cd\u09a6\u09bf\u09b0\u099f\u09bf \u0996\u09c1\u0981\u099c\u09c1\u09a8\u0964"],t.w)
B.asi=new A.D(B.R,["Notice the colorful Buddhist prayer flags fluttering along the dirt mountain trail.","\u09ae\u09be\u099f\u09bf\u09f0 \u09aa\u09be\u09b9\u09be\u09f0\u09c0\u09af\u09bc\u09be \u09ac\u09be\u099f\u09f0 \u0995\u09be\u09b7\u09a4 \u09ac\u09a4\u09be\u09b9\u09a4 \u0989\u09f0\u09bf \u09a5\u0995\u09be \u0989\u099c\u09cd\u099c\u09cd\u09ac\u09b2 \u09f0\u0999\u09f0 \u09aa\u09cd\u09f0\u09be\u09f0\u09cd\u09a5\u09a8\u09be\u09f0 \u09aa\u09a4\u09be\u0995\u09be\u09ac\u09cb\u09f0 \u099a\u09be\u0993\u0995\u0964","\u092a\u0939\u093e\u0921\u093c\u0940 \u092a\u0917\u0921\u0902\u0921\u0940 \u0915\u0947 \u0915\u093f\u0928\u093e\u0930\u0947 \u0939\u0935\u093e \u092e\u0947\u0902 \u092b\u0939\u0930\u093e\u0924\u0940 \u0930\u0902\u0917-\u092c\u093f\u0930\u0902\u0917\u0940 \u092a\u0935\u093f\u0924\u094d\u0930 \u092a\u094d\u0930\u093e\u0930\u094d\u0925\u0928\u093e \u0927\u094d\u0935\u091c \u0926\u0947\u0916\u0947\u0902\u0964","\u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u09ae\u09c7\u09a0\u09cb \u09aa\u09a5\u09c7\u09b0 \u09a7\u09be\u09b0\u09c7 \u09ac\u09be\u09a4\u09be\u09b8\u09c7 \u0989\u09a1\u09bc\u09a4\u09c7 \u09a5\u09be\u0995\u09be \u09b0\u0999\u09bf\u09a8 \u09aa\u09cd\u09b0\u09be\u09b0\u09cd\u09a5\u09a8\u09be\u09b0 \u09aa\u09a4\u09be\u0995\u09be\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.at8=new A.D(B.l3,[B.asB,B.arN,B.asN,B.as_,B.asO,B.asa,B.arX,B.asx,B.asf,B.asH,B.asd,B.asi],t.vb)
B.arS=new A.D(B.R,["Look for the golden embossed prayer wheels and richly painted Buddhist thangka murals.","\u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u09aa\u09cd\u09f0\u09be\u09f0\u09cd\u09a5\u09a8\u09be\u09f0 \u099a\u0995\u09be \u0986\u09f0\u09c1 \u09a6\u09c7\u09f1\u09be\u09b2\u09a4 \u0985\u0981\u0995\u09be \u09a7\u09c1\u09a8\u09c0\u09af\u09bc\u09be \u09ac\u09cc\u09a6\u09cd\u09a7 \u099a\u09bf\u09a4\u09cd\u09f0\u09ac\u09cb\u09f0\u09f0 \u0985\u0982\u09b6\u099f\u09cb \u099a\u09be\u0993\u0995\u0964","\u0938\u0941\u0928\u0939\u0930\u0947 \u092a\u094d\u0930\u093e\u0930\u094d\u0925\u0928\u093e \u091a\u0915\u094d\u0930 \u0914\u0930 \u0926\u0940\u0935\u093e\u0930 \u092a\u0930 \u092c\u0928\u0947 \u0930\u0902\u0917-\u092c\u093f\u0930\u0902\u0917\u0947 \u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u0925\u0902\u0917\u0915\u093e \u091a\u093f\u0924\u094d\u0930 \u0926\u0947\u0916\u0947\u0902\u0964","\u09b8\u09cb\u09a8\u09be\u09b2\u09c0 \u09aa\u09cd\u09b0\u09be\u09b0\u09cd\u09a5\u09a8\u09be\u09b0 \u099a\u09be\u0995\u09be \u098f\u09ac\u0982 \u09a6\u09c7\u09af\u09bc\u09be\u09b2\u09c7 \u0986\u0981\u0995\u09be \u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u0990\u09a4\u09bf\u09b9\u09cd\u09af\u09ac\u09be\u09b9\u09c0 \u09a5\u09be\u0982\u0995\u09be \u099a\u09bf\u09a4\u09cd\u09b0\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.as5=new A.D(B.R,["Find the serene monk seated in peaceful meditation before the luminous golden Buddha statue.","\u0989\u099c\u09cd\u099c\u09cd\u09ac\u09b2 \u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u09ac\u09c1\u09a6\u09cd\u09a7 \u09ae\u09c2\u09f0\u09cd\u09a4\u09bf\u09f0 \u09b8\u09a8\u09cd\u09ae\u09c1\u0996\u09a4 \u0997\u09ad\u09c0\u09f0 \u09a7\u09cd\u09af\u09be\u09a8\u09a4 \u09ae\u0997\u09cd\u09a8 \u09b9\u09c8 \u09a5\u0995\u09be \u09b6\u09be\u09a8\u09cd\u09a4 \u09ad\u09bf\u0995\u09cd\u0996\u09c1\u099c\u09a8\u0995 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u091a\u092e\u0915\u0924\u0940 \u0938\u0941\u0928\u0939\u0930\u0940 \u092c\u0941\u0926\u094d\u0927 \u092a\u094d\u0930\u0924\u093f\u092e\u093e \u0915\u0947 \u0906\u0917\u0947 \u0936\u093e\u0902\u0924 \u0927\u094d\u092f\u093e\u0928 \u092e\u0947\u0902 \u092c\u0948\u0920\u0947 \u092d\u093f\u0915\u094d\u0937\u0941 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u0989\u099c\u09cd\u099c\u09cd\u09ac\u09b2 \u09b8\u09cb\u09a8\u09be\u09b2\u09c0 \u09ac\u09c1\u09a6\u09cd\u09a7\u09ae\u09c2\u09b0\u09cd\u09a4\u09bf\u09b0 \u09b8\u09be\u09ae\u09a8\u09c7 \u09b6\u09be\u09a8\u09cd\u09a4 \u09a7\u09cd\u09af\u09be\u09a8\u09c7 \u09ac\u09b8\u09be \u09ac\u09cc\u09a6\u09cd\u09a7 \u09b8\u09a8\u09cd\u09a8\u09cd\u09af\u09be\u09b8\u09c0\u099f\u09bf\u0995\u09c7 \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asp=new A.D(B.R,["Notice the intricately carved temple pillar tops and the painted halo of the sacred deity.","\u09ae\u09a8\u09cd\u09a6\u09bf\u09f0\u09f0 \u09b8\u09cd\u09a4\u09ae\u09cd\u09ad\u09f0 \u0993\u09aa\u09f0\u09f0 \u0996\u09cb\u09a6\u09bf\u09a4 \u09a8\u0995\u09cd\u09b8\u09be \u0986\u09f0\u09c1 \u09a6\u09c7\u09f1\u09be\u09b2\u09a4 \u0985\u0981\u0995\u09be \u09ac\u09c1\u09a6\u09cd\u09a7\u09f0 \u09aa\u09ac\u09bf\u09a4\u09cd\u09f0 \u09aa\u09cd\u09f0\u09ad\u09be\u09ae\u09a3\u09cd\u09a1\u09b2 \u099a\u09be\u0993\u0995\u0964","\u0916\u0902\u092d\u094b\u0902 \u092a\u0930 \u0928\u0915\u094d\u0915\u093e\u0936\u0940\u0926\u093e\u0930 \u0938\u094b\u0928\u0947 \u0915\u093e \u0915\u093e\u092e \u0914\u0930 \u0926\u0940\u0935\u093e\u0930 \u092a\u0930 \u091a\u093f\u0924\u094d\u0930\u093f\u0924 \u092a\u0935\u093f\u0924\u094d\u0930 \u092c\u0941\u0926\u094d\u0927 \u0915\u093e \u092a\u094d\u0930\u092d\u093e\u092e\u0902\u0921\u0932 \u0926\u0947\u0916\u0947\u0902\u0964","\u09b8\u09cd\u09a4\u09ae\u09cd\u09ad\u09c7\u09b0 \u0993\u09aa\u09b0 \u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u0996\u09cb\u09a6\u09be\u0987 \u0995\u09b0\u09be \u0995\u09be\u09b0\u09c1\u0995\u09be\u099c \u098f\u09ac\u0982 \u09a6\u09c7\u09af\u09bc\u09be\u09b2\u09c7 \u0986\u0981\u0995\u09be \u09aa\u09ac\u09bf\u09a4\u09cd\u09b0 \u09ac\u09c1\u09a6\u09cd\u09a7\u09c7\u09b0 \u099c\u09cd\u09af\u09cb\u09a4\u09bf\u09b0\u09cd\u09ac\u09b2\u09af\u09bc \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asr=new A.D(B.R,["Look for the ornate ceiling beams with lotus carvings and traditional Tibetan wall frescoes.","\u09aa\u09a6\u09cd\u09ae\u09ab\u09c1\u09b2\u09f0 \u09a8\u0995\u09cd\u09b8\u09be \u09a5\u0995\u09be \u099a\u09bf\u09b2\u09bf\u0999\u09f0 \u0995\u09be\u09a0 \u0986\u09f0\u09c1 \u09aa\u09f0\u09ae\u09cd\u09aa\u09f0\u09be\u0997\u09a4 \u09a4\u09bf\u09ac\u09cd\u09ac\u09a4\u09c0 \u09a6\u09c7\u09f1\u09be\u09b2 \u099a\u09bf\u09a4\u09cd\u09f0\u09ac\u09cb\u09f0 \u099a\u09be\u0993\u0995\u0964","\u0915\u092e\u0932 \u0915\u0940 \u0928\u0915\u094d\u0915\u093e\u0936\u0940 \u0935\u093e\u0932\u0940 \u091b\u0924 \u0915\u0940 \u092c\u0932\u094d\u0932\u093f\u092f\u093e\u0902 \u0914\u0930 \u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u0924\u093f\u092c\u094d\u092c\u0924\u0940 \u092d\u093f\u0924\u094d\u0924\u093f\u091a\u093f\u0924\u094d\u0930 \u0926\u0947\u0916\u0947\u0902\u0964","\u09aa\u09a6\u09cd\u09ae\u09c7\u09b0 \u0995\u09be\u09b0\u09c1\u0995\u09be\u099c \u0995\u09b0\u09be \u099b\u09be\u09a6\u09c7\u09b0 \u09ac\u09bf\u09ae \u098f\u09ac\u0982 \u0990\u09a4\u09bf\u09b9\u09cd\u09af\u09ac\u09be\u09b9\u09c0 \u09a4\u09bf\u09ac\u09cd\u09ac\u09a4\u09bf \u09a6\u09c7\u09af\u09bc\u09be\u09b2\u099a\u09bf\u09a4\u09cd\u09b0\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asg=new A.D(B.R,["Find the row of brass prayer cylinders and the carved wooden sanctuary pillars.","\u09aa\u09bf\u09a4\u09b2\u09f0 \u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u09aa\u09cd\u09f0\u09be\u09f0\u09cd\u09a5\u09a8\u09be \u099a\u0995\u09be\u09ac\u09cb\u09f0 \u0986\u09f0\u09c1 \u0995\u09be\u09a0\u09f0 \u0996\u09cb\u09a6\u09bf\u09a4 \u09b8\u09cd\u09a4\u09ae\u09cd\u09ad\u0995\u09c7\u0987\u099f\u09be \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u092a\u0940\u0924\u0932 \u0915\u0947 \u092a\u094d\u0930\u093e\u0930\u094d\u0925\u0928\u093e \u091a\u0915\u094d\u0930\u094b\u0902 \u0915\u0940 \u0915\u0924\u093e\u0930 \u0914\u0930 \u0928\u0915\u094d\u0915\u093e\u0936\u0940\u0926\u093e\u0930 \u0932\u0915\u0921\u093c\u0940 \u0915\u0947 \u0916\u0902\u092d\u0947 \u0916\u094b\u091c\u0947\u0902\u0964","\u09aa\u09bf\u09a4\u09b2\u09c7\u09b0 \u09aa\u09cd\u09b0\u09be\u09b0\u09cd\u09a5\u09a8\u09be\u09b0 \u099a\u09be\u0995\u09be\u09b0 \u09b8\u09be\u09b0\u09bf \u098f\u09ac\u0982 \u0995\u09be\u09b0\u09c1\u0995\u09be\u099c \u0995\u09b0\u09be \u0995\u09be\u09a0\u09c7\u09b0 \u09a5\u09be\u09ae\u0997\u09c1\u09b2\u09cb \u0996\u09c1\u0981\u099c\u09c1\u09a8\u0964"],t.w)
B.asQ=new A.D(B.R,["Look for the peaceful monk sitting in meditation on the white steps before Lord Buddha.","\u09ad\u0997\u09f1\u09be\u09a8 \u09ac\u09c1\u09a6\u09cd\u09a7\u09f0 \u0986\u0997\u09a4 \u09ac\u0997\u09be \u0996\u099f\u0996\u099f\u09bf\u09a4 \u09b6\u09be\u09a8\u09cd\u09a4\u09ad\u09be\u09f1\u09c7 \u09a7\u09cd\u09af\u09be\u09a8\u09a4 \u09ac\u09b9\u09be \u09b8\u09a8\u09cd\u09a8\u09cd\u09af\u09be\u09b8\u09c0\u099c\u09a8\u0995 \u099a\u09be\u0993\u0995\u0964","\u092d\u0917\u0935\u093e\u0928 \u092c\u0941\u0926\u094d\u0927 \u0915\u0947 \u0938\u093e\u092e\u0928\u0947 \u0938\u092b\u0947\u0926 \u0938\u0940\u0922\u093c\u093f\u092f\u094b\u0902 \u092a\u0930 \u0936\u093e\u0902\u0924 \u0927\u094d\u092f\u093e\u0928\u092e\u0917\u094d\u0928 \u092c\u0948\u0920\u0947 \u092d\u093f\u0915\u094d\u0937\u0941 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u09ad\u0997\u09ac\u09be\u09a8 \u09ac\u09c1\u09a6\u09cd\u09a7\u09c7\u09b0 \u09b8\u09be\u09ae\u09a8\u09c7 \u09b8\u09be\u09a6\u09be \u09b8\u09bf\u0981\u09a1\u09bc\u09bf\u09a4\u09c7 \u09b6\u09be\u09a8\u09cd\u09a4 \u09a7\u09cd\u09af\u09be\u09a8\u09c7 \u09ac\u09b8\u09be \u09b8\u09a8\u09cd\u09a8\u09cd\u09af\u09be\u09b8\u09c0\u099f\u09bf\u0995\u09c7 \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asJ=new A.D(B.R,["Look for the painted temple archway with gold floral borders and colorful frescoes.","\u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u09ab\u09c1\u09b2\u09f0 \u09a8\u0995\u09cd\u09b8\u09be \u0986\u09f0\u09c1 \u09f0\u0999\u09c0\u09a8 \u099a\u09bf\u09a4\u09cd\u09f0\u09f0\u09c7 \u09b8\u099c\u09cb\u09f1\u09be \u09ae\u09a8\u09cd\u09a6\u09bf\u09f0\u09f0 \u09a4\u09cb\u09f0\u09a3\u09f0 \u0985\u0982\u09b6\u099f\u09cb \u099a\u09be\u0993\u0995\u0964","\u0938\u0941\u0928\u0939\u0930\u0940 \u092a\u0941\u0937\u094d\u092a \u0928\u0915\u094d\u0915\u093e\u0936\u0940 \u0914\u0930 \u0938\u0941\u0902\u0926\u0930 \u0930\u0902\u0917\u094b\u0902 \u0938\u0947 \u0938\u091c\u093e \u092e\u0902\u0926\u093f\u0930 \u0915\u0947 \u092a\u094d\u0930\u0935\u0947\u0936 \u0915\u093e \u0924\u094b\u0930\u0923 \u0926\u0947\u0916\u0947\u0902\u0964","\u09b8\u09cb\u09a8\u09be\u09b2\u09c0 \u09ab\u09c1\u09b2\u09c7\u09b0 \u0995\u09be\u09b0\u09c1\u0995\u09be\u099c \u0993 \u09b0\u0999\u09bf\u09a8 \u099a\u09bf\u09a4\u09cd\u09b0\u09c7 \u09b8\u09be\u099c\u09be\u09a8\u09cb \u09ae\u09a8\u09cd\u09a6\u09bf\u09b0\u09c7\u09b0 \u0996\u09bf\u09b2\u09be\u09a8\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asD=new A.D(B.R,["Find the radiant golden Buddha statue seated with hand in the earth-touching gesture.","\u09ad\u09c2\u09ae\u09bf\u09b8\u09cd\u09aa\u09f0\u09cd\u09b6 \u09ae\u09c1\u09a6\u09cd\u09f0\u09be\u09a4 \u09b6\u09be\u09a8\u09cd\u09a4\u09ad\u09be\u09f1\u09c7 \u09ac\u09b9\u09bf \u09a5\u0995\u09be \u0989\u099c\u09cd\u099c\u09cd\u09ac\u09b2 \u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u09ac\u09c1\u09a6\u09cd\u09a7 \u09ae\u09c2\u09f0\u09cd\u09a4\u09bf\u099f\u09cb \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u092d\u0942\u092e\u093f\u0938\u094d\u092a\u0930\u094d\u0936 \u092e\u0941\u0926\u094d\u0930\u093e \u092e\u0947\u0902 \u0935\u093f\u0930\u093e\u091c\u092e\u093e\u0928 \u091a\u092e\u0915\u0924\u0940 \u0938\u0941\u0928\u0939\u0930\u0940 \u092c\u0941\u0926\u094d\u0927 \u092a\u094d\u0930\u0924\u093f\u092e\u093e \u0915\u094b \u0916\u094b\u091c\u0947\u0902\u0964","\u09ad\u09c2\u09ae\u09bf \u09b8\u09cd\u09aa\u09b0\u09cd\u09b6 \u09ae\u09c1\u09a6\u09cd\u09b0\u09be\u09af\u09bc \u09b6\u09be\u09a8\u09cd\u09a4\u09ad\u09be\u09ac\u09c7 \u09ac\u09b8\u09c7 \u09a5\u09be\u0995\u09be \u0989\u099c\u09cd\u099c\u09cd\u09ac\u09b2 \u09b8\u09cb\u09a8\u09be\u09b2\u09c0 \u09ac\u09c1\u09a6\u09cd\u09a7\u09ae\u09c2\u09b0\u09cd\u09a4\u09bf\u099f\u09bf \u0996\u09c1\u0981\u099c\u09c1\u09a8\u0964"],t.w)
B.arW=new A.D(B.R,["Notice the colorful mural of the compassionate Bodhisattva painted on the temple wall.","\u09ae\u09a8\u09cd\u09a6\u09bf\u09f0\u09f0 \u09a6\u09c7\u09f1\u09be\u09b2\u09a4 \u0985\u0981\u0995\u09be \u0995\u09f0\u09c1\u09a3\u09be\u09ae\u09af\u09bc \u09ac\u09cb\u09a7\u09bf\u09b8\u09a4\u09cd\u09a4\u09cd\u09ac\u09f0 \u09f0\u0999\u09c0\u09a8 \u09a6\u09c7\u09f1\u09be\u09b2 \u099a\u09bf\u09a4\u09cd\u09f0\u0996\u09a8 \u09b2\u0995\u09cd\u09b7\u09cd\u09af \u0995\u09f0\u0995\u0964","\u092e\u0902\u0926\u093f\u0930 \u0915\u0940 \u0926\u0940\u0935\u093e\u0930 \u092a\u0930 \u091a\u093f\u0924\u094d\u0930\u093f\u0924 \u0915\u0930\u0941\u0923\u093e\u092e\u092f\u0940 \u092c\u094b\u0927\u093f\u0938\u0924\u094d\u0935 \u0915\u093e \u0938\u0941\u0902\u0926\u0930 \u0930\u0902\u0917\u0940\u0928 \u0930\u0942\u092a \u0926\u0947\u0916\u0947\u0902\u0964","\u09ae\u09a8\u09cd\u09a6\u09bf\u09b0\u09c7\u09b0 \u09a6\u09c7\u09af\u09bc\u09be\u09b2\u09c7 \u0986\u0981\u0995\u09be \u0995\u09b0\u09c1\u09a3\u09be\u09ae\u09af\u09bc \u09ac\u09cb\u09a7\u09bf\u09b8\u09a4\u09cd\u09a4\u09cd\u09ac\u09c7\u09b0 \u09b0\u0999\u09bf\u09a8 \u09b0\u09c2\u09aa\u099f\u09bf \u09b2\u0995\u09cd\u09b7\u09cd\u09af \u0995\u09b0\u09c1\u09a8\u0964"],t.w)
B.asK=new A.D(B.R,["Look for the large golden prayer cylinders set into the wooden temple frame.","\u0995\u09be\u09a0\u09f0 \u09ab\u09cd\u09f0\u09c7\u09ae\u09f0 \u09ae\u09be\u099c\u09a4 \u09a5\u0995\u09be \u09a1\u09be\u0999\u09f0 \u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u09aa\u09cd\u09f0\u09be\u09f0\u09cd\u09a5\u09a8\u09be\u09f0 \u099a\u0995\u09be\u09ac\u09cb\u09f0 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0932\u0915\u0921\u093c\u0940 \u0915\u0947 \u091a\u094c\u0916\u091f \u092e\u0947\u0902 \u0932\u0917\u0947 \u092c\u0921\u093c\u0947 \u0938\u0941\u0928\u0939\u0930\u0947 \u092a\u094d\u0930\u093e\u0930\u094d\u0925\u0928\u093e \u091a\u0915\u094d\u0930\u094b\u0902 \u0935\u093e\u0932\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u0926\u0947\u0916\u0947\u0902\u0964","\u0995\u09be\u09a0\u09c7\u09b0 \u09ab\u09cd\u09b0\u09c7\u09ae\u09c7\u09b0 \u09ad\u09c7\u09a4\u09b0 \u09ac\u09b8\u09be\u09a8\u09cb \u09ac\u09a1\u09bc \u09b8\u09cb\u09a8\u09be\u09b2\u09c0 \u09aa\u09cd\u09b0\u09be\u09b0\u09cd\u09a5\u09a8\u09be\u09b0 \u099a\u09be\u0995\u09be\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.ass=new A.D(B.R,["Find the young monk draped in traditional maroon robes sitting peacefully in meditation.","\u09f0\u0999\u099a\u09c1\u09f1\u09be \u09ac\u09b8\u09cd\u09a4\u09cd\u09f0 \u09aa\u09f0\u09bf\u09b9\u09bf\u09a4 \u09b9\u09c8 \u0997\u09ad\u09c0\u09f0 \u09a7\u09cd\u09af\u09be\u09a8\u09a4 \u09a8\u09bf\u09ae\u0997\u09cd\u09a8 \u09b6\u09be\u09a8\u09cd\u09a4 \u09a4\u09f0\u09c1\u09a3 \u09b8\u09a8\u09cd\u09a8\u09cd\u09af\u09be\u09b8\u09c0\u099c\u09a8\u0995 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u0917\u0939\u0930\u0947 \u0932\u093e\u0932 \u0935\u0938\u094d\u0924\u094d\u0930 \u092a\u0939\u0928\u0947 \u0936\u093e\u0902\u0924 \u092d\u093e\u0935 \u0938\u0947 \u0927\u094d\u092f\u093e\u0928 \u092e\u0947\u0902 \u0932\u0940\u0928 \u092d\u093f\u0915\u094d\u0937\u0941 \u0915\u094b \u0916\u094b\u091c\u0947\u0902\u0964","\u0990\u09a4\u09bf\u09b9\u09cd\u09af\u09ac\u09be\u09b9\u09c0 \u0997\u09be\u09a2\u09bc \u09b2\u09be\u09b2 \u09aa\u09cb\u09b6\u09be\u0995 \u09aa\u09b0\u09be \u09b6\u09be\u09a8\u09cd\u09a4 \u09ae\u09a8\u09c7 \u09a7\u09cd\u09af\u09be\u09a8\u09c7 \u09ae\u0997\u09cd\u09a8 \u09a4\u09b0\u09c1\u09a3 \u09b8\u09a8\u09cd\u09a8\u09cd\u09af\u09be\u09b8\u09c0\u099f\u09bf\u0995\u09c7 \u0996\u09c1\u0981\u099c\u09c1\u09a8\u0964"],t.w)
B.ask=new A.D(B.R,["Notice the decorated monastery entrance pillars and the sacred prayer wheels.","\u09b8\u099c\u09be\u0987 \u09a4\u09cb\u09b2\u09be \u09ae\u09a8\u09cd\u09a6\u09bf\u09f0\u09f0 \u09b8\u09cd\u09a4\u09ae\u09cd\u09ad \u0986\u09f0\u09c1 \u09aa\u09ac\u09bf\u09a4\u09cd\u09f0 \u09aa\u09cd\u09f0\u09be\u09f0\u09cd\u09a5\u09a8\u09be\u09f0 \u0998\u09c2\u09f0\u09cd\u09a3\u09a8 \u099a\u0995\u09be\u09ac\u09cb\u09f0 \u09b2\u0995\u09cd\u09b7\u09cd\u09af \u0995\u09f0\u0995\u0964","\u0938\u091c\u093e\u090f \u0917\u090f \u092e\u0902\u0926\u093f\u0930 \u0915\u0947 \u0916\u0902\u092d\u0947 \u0914\u0930 \u0909\u0928\u0915\u0947 \u092a\u093e\u0938 \u0932\u0917\u0947 \u092a\u0935\u093f\u0924\u094d\u0930 \u092a\u094d\u0930\u093e\u0930\u094d\u0925\u0928\u093e \u091a\u0915\u094d\u0930 \u0926\u0947\u0916\u0947\u0902\u0964","\u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u0995\u09b0\u09c7 \u09b8\u09be\u099c\u09be\u09a8\u09cb \u09ae\u09a8\u09cd\u09a6\u09bf\u09b0\u09c7\u09b0 \u09b8\u09cd\u09a4\u09ae\u09cd\u09ad \u098f\u09ac\u0982 \u09aa\u09be\u09b6\u09c7 \u09a5\u09be\u0995\u09be \u09aa\u09ac\u09bf\u09a4\u09cd\u09b0 \u09aa\u09cd\u09b0\u09be\u09b0\u09cd\u09a5\u09a8\u09be\u09b0 \u099a\u09be\u0995\u09be\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.ata=new A.D(B.l3,[B.arS,B.as5,B.asp,B.asr,B.asg,B.asQ,B.asJ,B.asD,B.arW,B.asK,B.ass,B.ask],t.vb)
B.asn=new A.D(B.R,["Look for the women from Arunachal, Assam, and Manipur dressed in golden Muga silk, traditional shawls, and beaded necklaces.","\u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u09ae\u09c1\u0997\u09be\u09f0 \u09ae\u09c7\u0996\u09c7\u09b2\u09be \u099a\u09be\u09a6\u09f0, \u09aa\u09f0\u09ae\u09cd\u09aa\u09f0\u09be\u0997\u09a4 \u099a\u09be\u09a6\u09f0 \u0986\u09f0\u09c1 \u09ae\u09a3\u09bf\u09f0\u09c7 \u09b8\u099c\u09be \u0985\u09f0\u09c1\u09a3\u09be\u099a\u09b2, \u0985\u09b8\u09ae \u0986\u09f0\u09c1 \u09ae\u09a3\u09bf\u09aa\u09c1\u09f0\u09f0 \u09ac\u09cb\u09f1\u09be\u09f0\u09c0-\u099b\u09cb\u09f1\u09be\u09b2\u09c0\u0995\u09c7\u0987\u0997\u09f0\u09be\u0995\u09c0\u0995 \u099a\u09be\u0993\u0995\u0964","\u0905\u0930\u0941\u0923\u093e\u091a\u0932, \u0905\u0938\u092e \u0914\u0930 \u092e\u0923\u093f\u092a\u0941\u0930 \u0915\u0940 \u092e\u0939\u093f\u0932\u093e\u0913\u0902 \u0915\u094b \u0909\u0928\u0915\u0947 \u0938\u0941\u0928\u0939\u0930\u0947 \u092e\u0942\u0902\u0917\u093e \u0938\u093f\u0932\u094d\u0915, \u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u0936\u0949\u0932 \u0914\u0930 \u092e\u094b\u0924\u093f\u092f\u094b\u0902 \u0915\u0947 \u0939\u093e\u0930 \u092e\u0947\u0902 \u0926\u0947\u0916\u0947\u0902\u0964","\u0985\u09b0\u09c1\u09a3\u09be\u099a\u09b2, \u0986\u09b8\u09be\u09ae \u0993 \u09ae\u09a3\u09bf\u09aa\u09c1\u09b0\u09c7\u09b0 \u09ae\u09b9\u09bf\u09b2\u09be\u09a6\u09c7\u09b0 \u09b8\u09cb\u09a8\u09be\u09b2\u09c0 \u09ae\u09c1\u0997\u09be \u09b8\u09bf\u09b2\u09cd\u0995\u09c7\u09b0 \u09b6\u09be\u09a1\u09bc\u09bf, \u0990\u09a4\u09bf\u09b9\u09cd\u09af\u09ac\u09be\u09b9\u09c0 \u09b6\u09be\u09b2 \u0993 \u0997\u09b9\u09a8\u09be\u09af\u09bc \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asw=new A.D(B.R,["Find the women from Meghalaya, Mizoram, Nagaland, and Tripura in their vivid red handwoven skirts and traditional headdresses.","\u09ae\u09c7\u0998\u09be\u09b2\u09af\u09bc, \u09ae\u09bf\u099c\u09cb\u09f0\u09be\u09ae, \u09a8\u09be\u0997\u09be\u09b2\u09c7\u09a3\u09cd\u09a1 \u0986\u09f0\u09c1 \u09a4\u09cd\u09f0\u09bf\u09aa\u09c1\u09f0\u09be\u09f0 \u09a7\u09c1\u09a8\u09c0\u09af\u09bc\u09be \u09f0\u0999\u09be \u0986\u09f0\u09c1 \u0995\u2019\u09b2\u09be \u09ac\u09cb\u09f1\u09be \u09b8\u09be\u099c \u09aa\u09f0\u09bf\u09b9\u09bf\u09a4 \u09ae\u09b9\u09bf\u09b2\u09be\u09b8\u0995\u09b2\u0995 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u092e\u0947\u0918\u093e\u0932\u092f, \u092e\u093f\u091c\u094b\u0930\u092e, \u0928\u093e\u0917\u093e\u0932\u0948\u0902\u0921 \u0914\u0930 \u0924\u094d\u0930\u093f\u092a\u0941\u0930\u093e \u0915\u0940 \u092e\u0939\u093f\u0932\u093e\u0913\u0902 \u0915\u094b \u0909\u0928\u0915\u0940 \u091a\u092e\u0915\u0940\u0932\u0940 \u0932\u093e\u0932 \u0939\u0925\u0915\u0930\u0918\u093e \u092a\u094b\u0936\u093e\u0915\u094b\u0902 \u0914\u0930 \u092e\u0941\u0915\u0941\u091f\u094b\u0902 \u092e\u0947\u0902 \u0926\u0947\u0916\u0947\u0902\u0964","\u09ae\u09c7\u0998\u09be\u09b2\u09af\u09bc, \u09ae\u09bf\u099c\u09cb\u09b0\u09be\u09ae, \u09a8\u09be\u0997\u09be\u09b2\u09cd\u09af\u09be\u09a8\u09cd\u09a1 \u0993 \u09a4\u09cd\u09b0\u09bf\u09aa\u09c1\u09b0\u09be\u09b0 \u09ae\u09b9\u09bf\u09b2\u09be\u09a6\u09c7\u09b0 \u0989\u099c\u09cd\u099c\u09cd\u09ac\u09b2 \u09b2\u09be\u09b2 \u09a4\u09be\u0981\u09a4\u09c7\u09b0 \u09aa\u09cb\u09b6\u09be\u0995 \u0993 \u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u09b8\u09be\u099c\u09c7 \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.arY=new A.D(B.R,["Notice the warm smiles of the sisters from Arunachal, Assam, and Manipur with lush green bamboo hills behind them.","\u09b8\u09c7\u0989\u099c\u09c0\u09af\u09bc\u09be \u09ac\u09be\u0981\u09b9\u09a8\u09bf \u0986\u09f0\u09c1 \u09aa\u09be\u09b9\u09be\u09f0\u09f0 \u09aa\u099f\u09ad\u09c2\u09ae\u09bf\u09a4 \u0985\u09f0\u09c1\u09a3\u09be\u099a\u09b2, \u0985\u09b8\u09ae \u0986\u09f0\u09c1 \u09ae\u09a3\u09bf\u09aa\u09c1\u09f0\u09f0 \u09b9\u09be\u0981\u09b9\u09bf\u09ae\u09c1\u0996\u09c0\u09af\u09bc\u09be \u099c\u09c0\u09af\u09bc\u09f0\u09c0\u09b8\u0995\u09b2\u0995 \u099a\u09be\u0993\u0995\u0964","\u0939\u0930\u0947-\u092d\u0930\u0947 \u092c\u093e\u0902\u0938 \u0915\u0947 \u091c\u0902\u0917\u0932\u094b\u0902 \u0914\u0930 \u092a\u0939\u093e\u0921\u093c\u093f\u092f\u094b\u0902 \u0915\u0947 \u0938\u093e\u092e\u0928\u0947 \u0905\u0930\u0941\u0923\u093e\u091a\u0932, \u0905\u0938\u092e \u0914\u0930 \u092e\u0923\u093f\u092a\u0941\u0930 \u0915\u0940 \u092c\u0939\u0928\u094b\u0902 \u0915\u0947 \u092e\u0941\u0938\u094d\u0915\u0941\u0930\u093e\u0924\u0947 \u091a\u0947\u0939\u0930\u0947 \u0926\u0947\u0916\u0947\u0902\u0964","\u09b8\u09ac\u09c1\u099c \u09ac\u09be\u0981\u09b6\u09ac\u09a8 \u0993 \u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u09b8\u09be\u09ae\u09a8\u09c7 \u0985\u09b0\u09c1\u09a3\u09be\u099a\u09b2, \u0986\u09b8\u09be\u09ae \u0993 \u09ae\u09a3\u09bf\u09aa\u09c1\u09b0\u09c7\u09b0 \u09ac\u09cb\u09a8\u09a6\u09c7\u09b0 \u09b8\u09cd\u09a8\u09bf\u0997\u09cd\u09a7 \u09b9\u09be\u09b8\u09bf\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.arR=new A.D(B.R,["Look for the smiling faces of the sisters representing Meghalaya, Mizoram, Nagaland, and Tripura against the misty rainforest.","\u0995\u09c1\u0981\u09f1\u09b2\u09c0\u09ad\u09f0\u09be \u0985\u09f0\u09a3\u09cd\u09af\u09f0 \u09b8\u09a8\u09cd\u09ae\u09c1\u0996\u09a4 \u09ae\u09c7\u0998\u09be\u09b2\u09af\u09bc, \u09ae\u09bf\u099c\u09cb\u09f0\u09be\u09ae, \u09a8\u09be\u0997\u09be\u09b2\u09c7\u09a3\u09cd\u09a1 \u0986\u09f0\u09c1 \u09a4\u09cd\u09f0\u09bf\u09aa\u09c1\u09f0\u09be\u09f0 \u09ae\u09f0\u09ae\u09b2\u0997\u09be \u09b9\u09be\u0981\u09b9\u09bf\u09ac\u09cb\u09f0 \u099a\u09be\u0993\u0995\u0964","\u0927\u0941\u0902\u0927\u0932\u0940 \u092a\u0939\u093e\u0921\u093c\u093f\u092f\u094b\u0902 \u0915\u0947 \u0906\u0917\u0947 \u092e\u0947\u0918\u093e\u0932\u092f, \u092e\u093f\u091c\u094b\u0930\u092e, \u0928\u093e\u0917\u093e\u0932\u0948\u0902\u0921 \u0914\u0930 \u0924\u094d\u0930\u093f\u092a\u0941\u0930\u093e \u0915\u0940 \u092e\u0941\u0938\u094d\u0915\u0941\u0930\u093e\u0924\u0940 \u092c\u0939\u0928\u094b\u0902 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u0995\u09c1\u09af\u09bc\u09be\u09b6\u09be\u099a\u09cd\u099b\u09a8\u09cd\u09a8 \u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u0995\u09cb\u09b2\u09c7 \u09ae\u09c7\u0998\u09be\u09b2\u09af\u09bc, \u09ae\u09bf\u099c\u09cb\u09b0\u09be\u09ae, \u09a8\u09be\u0997\u09be\u09b2\u09cd\u09af\u09be\u09a8\u09cd\u09a1 \u0993 \u09a4\u09cd\u09b0\u09bf\u09aa\u09c1\u09b0\u09be\u09b0 \u09b9\u09be\u09b8\u09bf\u09ae\u09c1\u0996 \u09ac\u09cb\u09a8\u09c7\u09b0\u09be\u0964"],t.w)
B.asR=new A.D(B.R,["Find the golden Assamese Mekhela Chador with red borders and woven bamboo baskets of fresh indigenous rice and fish.","\u09f0\u0999\u09be \u09ab\u09c1\u09b2 \u0995\u099f\u09be \u0985\u09b8\u09ae\u09f0 \u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u09ae\u09c7\u0996\u09c7\u09b2\u09be \u099a\u09be\u09a6\u09f0 \u0986\u09f0\u09c1 \u09ac\u09be\u0981\u09b9\u09f0 \u09aa\u09be\u099a\u09bf\u09a4 \u09a5\u0995\u09be \u09b8\u09cd\u09a5\u09be\u09a8\u09c0\u09af\u09bc \u09a7\u09be\u09a8 \u0986\u09f0\u09c1 \u09ae\u09be\u099b\u0996\u09bf\u09a8\u09bf \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0905\u0938\u092e \u0915\u0940 \u0932\u093e\u0932 \u0915\u093f\u0928\u093e\u0930\u0940 \u0935\u093e\u0932\u0940 \u0938\u0941\u0928\u0939\u0930\u0940 \u092e\u0947\u0916\u0947\u0932\u093e \u091a\u093e\u0926\u094b\u0930 \u0914\u0930 \u092c\u093e\u0902\u0938 \u0915\u0940 \u091f\u094b\u0915\u0930\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u0930\u0916\u093e \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u0905\u0928\u093e\u091c \u0935 \u092e\u091b\u0932\u0940 \u0916\u094b\u091c\u0947\u0902\u0964","\u0986\u09b8\u09be\u09ae\u09c7\u09b0 \u09b2\u09be\u09b2 \u09aa\u09be\u09a1\u09bc\u09c7\u09b0 \u09b8\u09cb\u09a8\u09be\u09b2\u09c0 \u09ae\u09c7\u0996\u09c7\u09b2\u09be \u099a\u09be\u09a6\u09b0 \u098f\u09ac\u0982 \u09ac\u09be\u0981\u09b6\u09c7\u09b0 \u09a1\u09be\u09b2\u09be\u09af\u09bc \u09b0\u09be\u0996\u09be \u09a6\u09c7\u09b6\u09c0\u09af\u09bc \u09a7\u09be\u09a8 \u0993 \u09ae\u09be\u099b\u09c7\u09b0 \u0985\u0982\u09b6\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.arU=new A.D(B.R,["Look for the woven bamboo bowls filled with tender bamboo shoots, fresh local produce, and vibrant tribal handloom fabrics.","\u09ac\u09be\u0981\u09b9\u09f0 \u0997\u09be\u0981\u099c, \u09b6\u09be\u0995-\u09aa\u09be\u099a\u09b2\u09bf \u0986\u09f0\u09c1 \u09f0\u0999\u09c0\u09a8 \u099c\u09a8\u099c\u09be\u09a4\u09c0\u09af\u09bc \u09ac\u09cb\u09f1\u09be \u0995\u09be\u09aa\u09cb\u09f0\u09f0 \u0985\u0982\u09b6\u099f\u09cb \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u092c\u093e\u0902\u0938 \u0915\u0947 \u0915\u0930\u0940\u0932, \u0924\u093e\u091c\u0940 \u092a\u0939\u093e\u0921\u093c\u0940 \u0938\u092c\u094d\u091c\u093f\u092f\u093e\u0902 \u0914\u0930 \u0930\u0902\u0917-\u092c\u093f\u0930\u0902\u0917\u0947 \u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u0935\u0938\u094d\u0924\u094d\u0930\u094b\u0902 \u0935\u093e\u0932\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u0926\u0947\u0916\u0947\u0902\u0964","\u09ac\u09be\u0981\u09b6\u09c7\u09b0 \u0995\u09cb\u0981\u09a1\u09bc\u09b2, \u09a4\u09be\u099c\u09be \u09b6\u09be\u0995\u09b8\u09ac\u099c\u09bf \u098f\u09ac\u0982 \u09b0\u0999\u09bf\u09a8 \u0990\u09a4\u09bf\u09b9\u09cd\u09af\u09ac\u09be\u09b9\u09c0 \u09a4\u09be\u0981\u09a4\u09c7\u09b0 \u09aa\u09cb\u09b6\u09be\u0995\u09c7\u09b0 \u0985\u0982\u09b6\u099f\u09bf \u0996\u09c1\u0981\u099c\u09c1\u09a8\u0964"],t.w)
B.asL=new A.D(B.R,["Notice the maiden of Arunachal in her silver bead necklace and the Assamese sister in golden silk.","\u09f0\u09c2\u09aa\u09be\u09b2\u09c0 \u09ae\u09a3\u09bf \u09aa\u09bf\u09a8\u09cd\u09a7\u09be \u0985\u09f0\u09c1\u09a3\u09be\u099a\u09b2\u09f0 \u099c\u09c0\u09af\u09bc\u09f0\u09c0 \u0986\u09f0\u09c1 \u09b8\u09cb\u09a3\u09be\u09b2\u09c0 \u09f0\u09c7\u099a\u09ae\u09f0 \u09b8\u09be\u099c\u09a4 \u0985\u09b8\u09ae\u09f0 \u099c\u09c0\u09af\u09bc\u09f0\u09c0\u0997\u09f0\u09be\u0995\u09c0\u0995 \u099a\u09be\u0993\u0995\u0964","\u092e\u094b\u0924\u093f\u092f\u094b\u0902 \u0915\u0947 \u0939\u093e\u0930 \u092e\u0947\u0902 \u0905\u0930\u0941\u0923\u093e\u091a\u0932 \u0915\u0940 \u0915\u0928\u094d\u092f\u093e \u0914\u0930 \u0938\u0941\u0928\u0939\u0930\u0947 \u0930\u0947\u0936\u092e \u092e\u0947\u0902 \u0905\u0938\u092e \u0915\u0940 \u092c\u0939\u0928 \u0915\u093e \u0930\u0942\u092a \u0926\u0947\u0916\u0947\u0902\u0964","\u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u0997\u09b9\u09a8\u09be \u09aa\u09b0\u09be \u0985\u09b0\u09c1\u09a3\u09be\u099a\u09b2\u09c7\u09b0 \u0995\u09a8\u09cd\u09af\u09be \u098f\u09ac\u0982 \u09b8\u09cb\u09a8\u09be\u09b2\u09c0 \u09b0\u09c7\u09b6\u09ae\u09bf \u09aa\u09cb\u09b6\u09be\u0995\u09c7 \u0986\u09b8\u09be\u09ae\u09c7\u09b0 \u09ac\u09cb\u09a8\u0995\u09c7 \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asu=new A.D(B.R,["Look for the graceful sisters of Manipur and Meghalaya with traditional neckpieces and soft shawls.","\u09ae\u09a3\u09bf\u09aa\u09c1\u09f0 \u0986\u09f0\u09c1 \u09ae\u09c7\u0998\u09be\u09b2\u09af\u09bc\u09f0 \u09b8\u09c1\u09a8\u09cd\u09a6\u09f0 \u09aa\u09f0\u09ae\u09cd\u09aa\u09f0\u09be\u0997\u09a4 \u09ae\u09be\u09b2\u09be \u0986\u09f0\u09c1 \u099a\u09be\u09a6\u09f0 \u09aa\u09f0\u09bf\u09b9\u09bf\u09a4\u09be \u099c\u09c0\u09af\u09bc\u09f0\u09c0\u09b8\u0995\u09b2\u0995 \u099a\u09be\u0993\u0995\u0964","\u092e\u0923\u093f\u092a\u0941\u0930 \u0914\u0930 \u092e\u0947\u0918\u093e\u0932\u092f \u0915\u0940 \u092c\u0939\u0928\u094b\u0902 \u0915\u0947 \u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u0939\u093e\u0930 \u0914\u0930 \u0938\u0941\u0902\u0926\u0930 \u0935\u0938\u094d\u0924\u094d\u0930\u094b\u0902 \u0935\u093e\u0932\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u0926\u0947\u0916\u0947\u0902\u0964","\u09ae\u09a3\u09bf\u09aa\u09c1\u09b0 \u0993 \u09ae\u09c7\u0998\u09be\u09b2\u09af\u09bc\u09c7\u09b0 \u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u0990\u09a4\u09bf\u09b9\u09cd\u09af\u09ac\u09be\u09b9\u09c0 \u0997\u09b9\u09a8\u09be \u0993 \u09aa\u09cb\u09b6\u09be\u0995 \u09aa\u09b0\u09be \u09ac\u09cb\u09a8\u09c7\u09a6\u09c7\u09b0 \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.as2=new A.D(B.R,["Find the sisters from Mizoram, Nagaland, and Tripura adorned in striking tribal headwear and woven regalia.","\u09ae\u09bf\u099c\u09cb\u09f0\u09be\u09ae, \u09a8\u09be\u0997\u09be\u09b2\u09c7\u09a3\u09cd\u09a1 \u0986\u09f0\u09c1 \u09a4\u09cd\u09f0\u09bf\u09aa\u09c1\u09f0\u09be\u09f0 \u09ac\u09c8\u09b6\u09bf\u09b7\u09cd\u099f\u09cd\u09af\u09aa\u09c2\u09f0\u09cd\u09a3 \u09b8\u09be\u099c \u0986\u09f0\u09c1 \u09b6\u09bf\u09f0\u09cb\u09b8\u09cd\u09a4\u09cd\u09f0\u09be\u09a3 \u09aa\u09f0\u09bf\u09b9\u09bf\u09a4\u09be \u09ad\u09a8\u09c0\u09b8\u0995\u09b2\u0995 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u092e\u093f\u091c\u094b\u0930\u092e, \u0928\u093e\u0917\u093e\u0932\u0948\u0902\u0921 \u0914\u0930 \u0924\u094d\u0930\u093f\u092a\u0941\u0930\u093e \u0915\u0940 \u092c\u0939\u0928\u094b\u0902 \u0915\u0947 \u0906\u0915\u0930\u094d\u0937\u0915 \u092e\u0941\u0915\u0941\u091f \u0914\u0930 \u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u0935\u0938\u094d\u0924\u094d\u0930 \u0916\u094b\u091c\u0947\u0902\u0964","\u09ae\u09bf\u099c\u09cb\u09b0\u09be\u09ae, \u09a8\u09be\u0997\u09be\u09b2\u09cd\u09af\u09be\u09a8\u09cd\u09a1 \u0993 \u09a4\u09cd\u09b0\u09bf\u09aa\u09c1\u09b0\u09be\u09b0 \u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u09ae\u09be\u09a5\u09be\u09b0 \u09b8\u09be\u099c \u0993 \u09ac\u09af\u09bc\u09a8\u09b6\u09bf\u09b2\u09cd\u09aa\u09c7\u09b0 \u09aa\u09cb\u09b6\u09be\u0995\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asC=new A.D(B.R,["Find the bamboo platters of traditional smoked fish, aromatic black rice, and harvested mountain grains.","\u09ac\u09be\u0981\u09b9\u09f0 \u09a1\u09b2\u09be\u09a4 \u09a5\u0995\u09be \u09aa\u09f0\u09ae\u09cd\u09aa\u09f0\u09be\u0997\u09a4 \u09b6\u09c1\u0995\u09be\u09a8 \u09ae\u09be\u099b, \u09b8\u09c1\u0997\u09a8\u09cd\u09a7\u09bf \u0995\u2019\u09b2\u09be \u099a\u09be\u0989\u09b2 \u0986\u09f0\u09c1 \u09aa\u09be\u09b9\u09be\u09f0\u09c0\u09af\u09bc\u09be \u09b6\u09b8\u09cd\u09af\u09ac\u09cb\u09f0 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u092c\u093e\u0902\u0938 \u0915\u0940 \u0925\u093e\u0932\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 \u0930\u0916\u0940 \u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u092e\u091b\u0932\u0940, \u0916\u0941\u0936\u092c\u0942\u0926\u093e\u0930 \u0915\u093e\u0932\u093e \u091a\u093e\u0935\u0932 \u0914\u0930 \u092a\u0939\u093e\u0921\u093c\u0940 \u0905\u0928\u093e\u091c \u0926\u0947\u0916\u0947\u0902\u0964","\u09ac\u09be\u0981\u09b6\u09c7\u09b0 \u09a1\u09be\u09b2\u09be\u09af\u09bc \u09b8\u09be\u099c\u09be\u09a8\u09cb \u09b8\u09c1\u09b8\u09cd\u09ac\u09be\u09a6\u09c1 \u0990\u09a4\u09bf\u09b9\u09cd\u09af\u09ac\u09be\u09b9\u09c0 \u09ae\u09be\u099b, \u09b8\u09c1\u0997\u09a8\u09cd\u09a7\u09bf \u0995\u09be\u09b2\u09cb \u099a\u09be\u09b2 \u0993 \u09b6\u09b8\u09cd\u09af\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.arP=new A.D(B.R,["Look for the fresh green herbs, tender bamboo shoots, and colorful handwoven wraparound fabrics.","\u09b8\u09a4\u09c7\u099c \u09ac\u09a8\u09cc\u09b7\u09a7\u09bf, \u09ac\u09be\u0981\u09b9\u09f0 \u0995\u09cb\u09ae\u09b2 \u0997\u09be\u0981\u099c \u0986\u09f0\u09c1 \u09f0\u0999\u09c0\u09a8 \u09b9\u09be\u09a4\u09b6\u09be\u09b2\u09f0 \u09ae\u09c7\u09f0\u09bf\u0993\u09f1\u09be \u0995\u09be\u09aa\u09cb\u09f0\u09ac\u09cb\u09f0 \u099a\u09be\u0993\u0995\u0964","\u0924\u093e\u091c\u093e \u0939\u0930\u093e \u0938\u093e\u0917, \u0928\u0930\u092e \u092c\u093e\u0902\u0938 \u0915\u0947 \u0915\u0930\u0940\u0932 \u0914\u0930 \u0930\u0902\u0917-\u092c\u093f\u0930\u0902\u0917\u0940 \u0939\u0925\u0915\u0930\u0918\u093e \u092a\u094b\u0936\u093e\u0915\u094b\u0902 \u0935\u093e\u0932\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u0926\u0947\u0916\u0947\u0902\u0964","\u09a4\u09be\u099c\u09be \u09b6\u09be\u0995\u09b8\u09ac\u099c\u09bf, \u0995\u099a\u09bf \u09ac\u09be\u0981\u09b6\u09c7\u09b0 \u0995\u09cb\u0981\u09a1\u09bc\u09b2 \u098f\u09ac\u0982 \u09b0\u0999\u09bf\u09a8 \u09a4\u09be\u0981\u09a4\u09c7\u09b0 \u0995\u09be\u09aa\u09a1\u09bc\u09c7\u09b0 \u0985\u0982\u09b6\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asm=new A.D(B.R,["Notice the handwoven red-and-black striped skirts resting beside bowls of orchard fruits and hill chilies.","\u09f0\u0999\u09be-\u0995\u2019\u09b2\u09be \u09aa\u099f\u09c0\u09af\u09bc\u09be \u09aa\u09f0\u09ae\u09cd\u09aa\u09f0\u09be\u0997\u09a4 \u0995\u09be\u09aa\u09cb\u09f0 \u0986\u09f0\u09c1 \u09ac\u09be\u099f\u09bf\u09a4 \u09b8\u099c\u09be\u0987 \u09a5\u09cb\u09f1\u09be \u09ab\u09b2\u09ae\u09c2\u09b2 \u0986\u09f0\u09c1 \u09ad\u09cb\u099f \u099c\u09b2\u0995\u09c0\u09af\u09bc\u09be \u099a\u09be\u0993\u0995\u0964","\u0932\u093e\u0932-\u0915\u093e\u0932\u0940 \u0927\u093e\u0930\u093f\u092f\u094b\u0902 \u0935\u093e\u0932\u0940 \u092a\u094b\u0936\u093e\u0915 \u0914\u0930 \u0915\u091f\u094b\u0930\u094b\u0902 \u092e\u0947\u0902 \u0930\u0916\u0947 \u092a\u0939\u093e\u0921\u093c\u0940 \u092b\u0932 \u0935 \u0924\u0940\u0916\u0940 \u092e\u093f\u0930\u094d\u091a \u0926\u0947\u0916\u0947\u0902\u0964","\u09b2\u09be\u09b2-\u0995\u09be\u09b2\u09cb \u09a1\u09cb\u09b0\u09be\u0995\u09be\u099f\u09be \u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u09aa\u09cb\u09b6\u09be\u0995 \u098f\u09ac\u0982 \u09ac\u09be\u099f\u09bf\u09a4\u09c7 \u09b0\u09be\u0996\u09be \u09b8\u09c1\u09b8\u09cd\u09ac\u09be\u09a6\u09c1 \u09ab\u09b2 \u0993 \u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09bf \u09ae\u09b0\u09bf\u099a \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.atb=new A.D(B.l3,[B.asn,B.asw,B.arY,B.arR,B.asR,B.arU,B.asL,B.asu,B.as2,B.asC,B.arP,B.asm],t.vb)
B.asA=new A.D(B.R,["Look for the deep rain-kissed green valley and the misty cloud cover drifting through the mountain gorges.","\u09ae\u09c7\u0998\u09c7\u09f0\u09c7 \u0986\u09ac\u09c3\u09a4 \u0997\u09ad\u09c0\u09f0 \u09b8\u09c7\u0989\u099c\u09c0\u09af\u09bc\u09be \u0989\u09aa\u09a4\u09cd\u09af\u0995\u09be \u0986\u09f0\u09c1 \u09aa\u09be\u09b9\u09be\u09f0\u09f0 \u0997\u09bf\u09f0\u09bf\u0996\u09be\u09a4\u09c7\u09a6\u09bf \u09ac\u09c8 \u09af\u09cb\u09f1\u09be \u09a8\u09a6\u09c0\u0996\u09a8 \u099a\u09be\u0993\u0995\u0964","\u092c\u093e\u0926\u0932\u094b\u0902 \u0938\u0947 \u0922\u0915\u0940 \u0917\u0939\u0930\u0940 \u0939\u0930\u0940 \u0918\u093e\u091f\u0940 \u0914\u0930 \u092a\u0939\u093e\u0921\u093c\u094b\u0902 \u0915\u0947 \u092c\u0940\u091a \u0938\u0947 \u0917\u0941\u091c\u0930\u0924\u0940 \u0927\u0941\u0902\u0927\u0932\u0940 \u0935\u093e\u0926\u093f\u092f\u094b\u0902 \u0915\u093e \u0928\u091c\u093e\u0930\u093e \u0926\u0947\u0916\u0947\u0902\u0964","\u09ae\u09c7\u0998\u09c7 \u09a2\u09be\u0995\u09be \u0997\u09ad\u09c0\u09b0 \u09b8\u09ac\u09c1\u099c \u0989\u09aa\u09a4\u09cd\u09af\u0995\u09be \u098f\u09ac\u0982 \u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u0996\u09be\u09a6 \u09a6\u09bf\u09af\u09bc\u09c7 \u09ac\u09af\u09bc\u09c7 \u09af\u09be\u0993\u09af\u09bc\u09be \u09a8\u09a6\u09c0\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.aso=new A.D(B.R,["Find the breathtaking white waterfalls plunging down the sheer cliffs and the hikers standing on the overlook.","\u09a5\u09bf\u09af\u09bc \u09aa\u09be\u09b9\u09be\u09f0\u09f0 \u09aa\u09f0\u09be \u09b8\u09f0\u09bf \u09aa\u09f0\u09be \u09a7\u09c1\u09a8\u09c0\u09af\u09bc\u09be \u09ac\u0997\u09be \u099c\u09b2\u09aa\u09cd\u09f0\u09aa\u09be\u09a4 \u0986\u09f0\u09c1 \u09aa\u09be\u09b9\u09be\u09f0\u09f0 \u09a6\u09be\u0981\u09a4\u09bf\u09a4 \u09a5\u09bf\u09af\u09bc \u09b9\u09c8 \u09a5\u0995\u09be \u09af\u09be\u09a4\u09cd\u09f0\u09c0\u09b8\u0995\u09b2\u0995 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u090a\u0902\u091a\u0947 \u092a\u0939\u093e\u0921\u093c\u094b\u0902 \u0938\u0947 \u0917\u093f\u0930\u0924\u0947 \u0938\u092b\u0947\u0926 \u0926\u0942\u0927\u093f\u092f\u093e \u091d\u0930\u0928\u0947 \u0914\u0930 \u092a\u0939\u093e\u0921\u093c\u0940 \u0930\u093e\u0938\u094d\u0924\u0947 \u092a\u0930 \u0916\u0921\u093c\u0947 \u092a\u0926\u092f\u093e\u0924\u094d\u0930\u093f\u092f\u094b\u0902 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u0989\u0981\u099a\u09c1 \u09aa\u09be\u09b9\u09be\u09a1\u09bc \u09a5\u09c7\u0995\u09c7 \u09a8\u09c7\u09ae\u09c7 \u0986\u09b8\u09be \u09b8\u09be\u09a6\u09be \u099c\u09b2\u09aa\u09cd\u09b0\u09aa\u09be\u09a4 \u098f\u09ac\u0982 \u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u099a\u09c2\u09a1\u09bc\u09be\u09af\u09bc \u09a6\u09be\u0981\u09a1\u09bc\u09bf\u09af\u09bc\u09c7 \u09a5\u09be\u0995\u09be \u09aa\u09a5\u09bf\u0995\u09a6\u09c7\u09b0 \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.arQ=new A.D(B.R,["Notice the swirling rain clouds and mist settling softly over the high plateaus of Cherrapunji.","\u099a\u09c7\u09f0\u09be\u09aa\u09c1\u099e\u09cd\u099c\u09c0\u09f0 \u0993\u0996 \u09aa\u09be\u09b9\u09be\u09f0\u09f0 \u0993\u09aa\u09f0\u09a4 \u0996\u09c7\u09b2\u09bf \u09a5\u0995\u09be \u09ac\u09f0\u09b7\u09c1\u09a3\u09f0 \u09a1\u09be\u09f1\u09f0 \u0986\u09f0\u09c1 \u0995\u09c1\u0981\u09f1\u09b2\u09c0\u09ac\u09cb\u09f0 \u09b2\u0995\u09cd\u09b7\u09cd\u09af \u0995\u09f0\u0995\u0964","\u091a\u0947\u0930\u093e\u092a\u0942\u0902\u091c\u0940 \u0915\u0947 \u090a\u0902\u091a\u0947 \u092a\u0920\u093e\u0930\u094b\u0902 \u092a\u0930 \u0924\u0948\u0930\u0924\u0947 \u092c\u093e\u0930\u093f\u0936 \u0915\u0947 \u092c\u093e\u0926\u0932 \u0914\u0930 \u0915\u094b\u0939\u0930\u0947 \u0915\u0940 \u091a\u093e\u0926\u0930 \u0926\u0947\u0916\u0947\u0902\u0964","\u099a\u09c7\u09b0\u09be\u09aa\u09c1\u099e\u09cd\u099c\u09bf\u09b0 \u0989\u0981\u099a\u09c1 \u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u0993\u09aa\u09b0 \u0998\u09c1\u09b0\u09c7 \u09ac\u09c7\u09a1\u09bc\u09be\u09a8\u09cb \u09ac\u09c3\u09b7\u09cd\u099f\u09bf\u09b0 \u09ae\u09c7\u0998 \u0993 \u0995\u09c1\u09af\u09bc\u09be\u09b6\u09be \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asI=new A.D(B.R,["Look for the sheer rocky cliff faces where multiple streams of water emerge from the jungle.","\u0985\u09f0\u09a3\u09cd\u09af\u09f0 \u09ae\u09be\u099c\u09c7\u09f0\u09c7 \u0993\u09b2\u09be\u0987 \u0985\u09b9\u09be \u09a5\u09bf\u09af\u09bc \u09b6\u09bf\u09b2\u09f0 \u09aa\u09be\u09b9\u09be\u09f0 \u0986\u09f0\u09c1 \u099c\u09b2\u09a7\u09be\u09f0\u09be\u09ac\u09cb\u09f0 \u099a\u09be\u0993\u0995\u0964","\u091c\u0902\u0917\u0932\u094b\u0902 \u0938\u0947 \u0928\u093f\u0915\u0932\u0915\u0930 \u090a\u0902\u091a\u0947 \u0938\u0940\u0927\u0947 \u091a\u091f\u094d\u091f\u093e\u0928\u094b\u0902 \u0938\u0947 \u0917\u093f\u0930\u0924\u0940 \u0915\u0908 \u091c\u0932\u0927\u093e\u0930\u093e\u0913\u0902 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u09b8\u09ac\u09c1\u099c \u099c\u0999\u09cd\u0997\u09b2 \u09ad\u09c7\u09a6 \u0995\u09b0\u09c7 \u09aa\u09be\u09a5\u09c1\u09b0\u09c7 \u09aa\u09be\u09b9\u09be\u09a1\u09bc \u09ac\u09c7\u09af\u09bc\u09c7 \u09a8\u09c7\u09ae\u09c7 \u0986\u09b8\u09be \u099c\u09b2\u09c7\u09b0 \u09a7\u09be\u09b0\u09be\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.ast=new A.D(B.R,["Find the lush green mountain ridge and the hikers with their walking sticks pausing to enjoy the view.","\u09b8\u09c7\u0989\u099c\u09c0\u09af\u09bc\u09be \u09aa\u09be\u09b9\u09be\u09f0\u09c0\u09af\u09bc\u09be \u09ac\u09be\u099f \u0986\u09f0\u09c1 \u09a6\u09c3\u09b6\u09cd\u09af \u0989\u09aa\u09ad\u09cb\u0997 \u0995\u09f0\u09bf \u09f0\u09c8 \u09a5\u0995\u09be \u09b2\u09be\u09a0\u09c0 \u09b9\u09be\u09a4\u09a4 \u09b2\u09c8 \u09af\u09be\u09a4\u09cd\u09f0\u09c0\u0995\u09c7\u0987\u099c\u09a8\u0995 \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0938\u0941\u0902\u0926\u0930 \u0939\u0930\u0940 \u092a\u0939\u093e\u0921\u093c\u0940 \u091a\u094b\u091f\u0940 \u0914\u0930 \u0939\u093e\u0925 \u092e\u0947\u0902 \u0932\u093e\u0920\u0940 \u0932\u093f\u090f \u0928\u091c\u093e\u0930\u0947 \u0915\u093e \u0906\u0928\u0902\u0926 \u0932\u0947\u0924\u0947 \u092f\u093e\u0924\u094d\u0930\u093f\u092f\u094b\u0902 \u0915\u094b \u0916\u094b\u091c\u0947\u0902\u0964","\u09b8\u09ac\u09c1\u099c \u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09bf \u09aa\u09a5 \u098f\u09ac\u0982 \u09a6\u09c3\u09b6\u09cd\u09af \u0989\u09aa\u09ad\u09cb\u0997 \u0995\u09b0\u09a4\u09c7 \u09b2\u09be\u09a0\u09bf \u09b9\u09be\u09a4\u09c7 \u09a6\u09be\u0981\u09a1\u09bc\u09bf\u09af\u09bc\u09c7 \u09a5\u09be\u0995\u09be \u09aa\u09b0\u09cd\u09af\u099f\u0995\u09a6\u09c7\u09b0 \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.ase=new A.D(B.R,["Look for the magnificent cascading waterfall crashing into the deep canyon pool below.","\u09a4\u09b2\u09f0 \u0997\u09ad\u09c0\u09f0 \u0989\u09aa\u09a4\u09cd\u09af\u0995\u09be\u09a4 \u09b8\u09b6\u09ac\u09cd\u09a6\u09c7 \u09b8\u09f0\u09bf \u09aa\u09f0\u09be \u09ac\u09bf\u09b6\u09be\u09b2 \u09ae\u09a8\u09cb\u09f0\u09ae \u099c\u09b2\u09aa\u09cd\u09f0\u09aa\u09be\u09a4\u099f\u09cb \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u0928\u0940\u091a\u0947 \u0917\u0939\u0930\u0940 \u0918\u093e\u091f\u0940 \u092e\u0947\u0902 \u0917\u0942\u0902\u091c\u0924\u0947 \u0939\u0941\u090f \u0917\u093f\u0930\u0924\u0947 \u0935\u093f\u0936\u093e\u0932 \u0914\u0930 \u0938\u0941\u0902\u0926\u0930 \u091d\u0930\u0928\u0947 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u09a8\u09bf\u099a\u09c7\u09b0 \u0997\u09ad\u09c0\u09b0 \u0996\u09be\u09a6\u09c7 \u0986\u099b\u09a1\u09bc\u09c7 \u09aa\u09a1\u09bc\u09be \u09ac\u09bf\u09b6\u09be\u09b2 \u09a8\u09af\u09bc\u09a8\u09be\u09ad\u09bf\u09b0\u09be\u09ae \u099c\u09b2\u09aa\u09cd\u09b0\u09aa\u09be\u09a4\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asl=new A.D(B.R,["Notice the monsoon clouds releasing a gentle haze of rain across the distant green peaks.","\u09a6\u09c2\u09f0\u09f0 \u09b8\u09c7\u0989\u099c\u09c0\u09af\u09bc\u09be \u09aa\u09be\u09b9\u09be\u09f0\u09f0 \u0993\u09aa\u09f0\u09a4 \u09ac\u09f0\u09b7\u09c1\u09a3\u09f0 \u0995\u09cb\u09ae\u09b2 \u0995\u09c1\u0981\u09f1\u09b2\u09c0 \u09aa\u09c7\u09b2\u09be\u0987 \u09a5\u0995\u09be \u09a1\u09be\u09f1\u09f0\u09ac\u09cb\u09f0 \u099a\u09be\u0993\u0995\u0964","\u0926\u0942\u0930 \u0915\u0940 \u0939\u0930\u0940 \u092a\u0939\u093e\u0921\u093c\u093f\u092f\u094b\u0902 \u092a\u0930 \u0939\u0932\u094d\u0915\u0940 \u092b\u0941\u0939\u093e\u0930\u0947\u0902 \u092c\u0930\u0938\u093e\u0924\u0947 \u092e\u093e\u0928\u0938\u0942\u0928\u0940 \u092c\u093e\u0926\u0932\u094b\u0902 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u09a6\u09c2\u09b0\u09c7\u09b0 \u09b8\u09ac\u09c1\u099c \u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u0993\u09aa\u09b0 \u09ac\u09c3\u09b7\u09cd\u099f\u09bf \u09ad\u09c7\u099c\u09be \u0995\u09c1\u09af\u09bc\u09be\u09b6\u09be \u099b\u09a1\u09bc\u09be\u09a8\u09cb \u09ae\u09c7\u0998\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.arZ=new A.D(B.R,["Look for the silver mountain river flowing quietly through the dense green valley bottom.","\u0989\u09aa\u09a4\u09cd\u09af\u0995\u09be\u09f0 \u09a4\u09b2\u09c7\u09a6\u09bf \u09b6\u09be\u09a8\u09cd\u09a4\u09ad\u09be\u09f1\u09c7 \u09ac\u09c8 \u09af\u09cb\u09f1\u09be \u09f0\u09c2\u09aa\u09be\u09b2\u09c0 \u09aa\u09be\u09b9\u09be\u09f0\u09c0\u09af\u09bc\u09be \u09a8\u09a6\u09c0\u0996\u09a8 \u099a\u09be\u0993\u0995\u0964","\u0918\u093e\u091f\u0940 \u0915\u0940 \u0917\u0939\u0930\u093e\u0908 \u092e\u0947\u0902 \u0936\u093e\u0902\u0924 \u092c\u0939\u0924\u0940 \u091a\u093e\u0902\u0926\u0940 \u091c\u0948\u0938\u0940 \u092a\u0939\u093e\u0921\u093c\u0940 \u0928\u0926\u0940 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u0989\u09aa\u09a4\u09cd\u09af\u0995\u09be\u09b0 \u09a4\u09b2\u09a6\u09c7\u09b6 \u09a6\u09bf\u09af\u09bc\u09c7 \u09b6\u09be\u09a8\u09cd\u09a4\u09ad\u09be\u09ac\u09c7 \u09ac\u09af\u09bc\u09c7 \u09af\u09be\u0993\u09af\u09bc\u09be \u09b0\u09c1\u09aa\u09cb\u09b2\u09bf \u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09bf \u09a8\u09a6\u09c0\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asv=new A.D(B.R,["Find the dramatic cliff edge where several white waterfalls begin their long plunge.","\u09af\u2019\u09f0 \u09aa\u09f0\u09be \u0995\u09c7\u0987\u09ac\u09be\u099f\u09be\u0993 \u09ac\u0997\u09be \u099c\u09b2\u09aa\u09cd\u09f0\u09aa\u09be\u09a4 \u09a4\u09b2\u09b2\u09c8 \u09a8\u09be\u09ae\u09bf \u0986\u09b9\u09bf\u099b\u09c7 \u09b8\u09c7\u0987 \u0993\u0996 \u09aa\u09be\u09b9\u09be\u09f0\u09f0 \u09a6\u09be\u0981\u09a4\u09bf\u099f\u09cb \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u092a\u0939\u093e\u0921\u093c \u0915\u093e \u0935\u0939 \u090a\u0902\u091a\u093e \u0915\u093f\u0928\u093e\u0930\u093e \u091c\u0939\u093e\u0902 \u0938\u0947 \u0915\u0908 \u0938\u092b\u0947\u0926 \u091d\u0930\u0928\u0947 \u0928\u0940\u091a\u0947 \u0915\u0940 \u0913\u0930 \u091b\u0932\u093e\u0902\u0917 \u0932\u0917\u093e\u0924\u0947 \u0939\u0948\u0902 \u0916\u094b\u091c\u0947\u0902\u0964","\u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u09b8\u09c7\u0987 \u0989\u0981\u099a\u09c1 \u0996\u09be\u09a1\u09bc\u09be \u09a7\u09be\u09b0\u099f\u09bf \u09af\u09c7\u0996\u09be\u09a8 \u09a5\u09c7\u0995\u09c7 \u09b6\u09c1\u09ad\u09cd\u09b0 \u099c\u09b2\u09aa\u09cd\u09b0\u09aa\u09be\u09a4\u0997\u09c1\u09b2\u09cb \u09a8\u09bf\u099a\u09c7\u09b0 \u09a6\u09bf\u0995\u09c7 \u09a8\u09c7\u09ae\u09c7 \u098f\u09b8\u09c7\u099b\u09c7\u0964"],t.w)
B.asb=new A.D(B.R,["Look for the small group of hikers standing on the red dirt path surrounded by ferns.","\u09a2\u09c7\u0995\u09c0\u09af\u09bc\u09be \u09b2\u09a4\u09be\u09f0\u09c7 \u09ad\u09f0\u09be \u09f0\u0999\u09be \u09ae\u09be\u099f\u09bf\u09f0 \u09ac\u09be\u099f\u09a4 \u09a5\u09bf\u09af\u09bc \u09b9\u09c8 \u09a5\u0995\u09be \u09af\u09be\u09a4\u09cd\u09f0\u09c0\u09f0 \u09a6\u09b2\u099f\u09cb\u0995 \u099a\u09be\u0993\u0995\u0964","\u092b\u0930\u094d\u0928 \u0915\u0947 \u092a\u094c\u0927\u094b\u0902 \u0915\u0947 \u092c\u0940\u091a \u0932\u093e\u0932 \u092e\u093f\u091f\u094d\u091f\u0940 \u0915\u0947 \u0930\u093e\u0938\u094d\u0924\u0947 \u092a\u0930 \u0916\u0921\u093c\u0947 \u092a\u0926\u092f\u093e\u0924\u094d\u0930\u093f\u092f\u094b\u0902 \u0915\u0947 \u0938\u092e\u0942\u0939 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u09ab\u09be\u09b0\u09cd\u09a8 \u0997\u09be\u099b\u09c7\u09b0 \u09ae\u09be\u099d\u09c7 \u09b2\u09be\u09b2 \u09ae\u09be\u099f\u09bf\u09b0 \u09ae\u09c7\u09a0\u09cb\u09aa\u09a5\u09c7 \u09a6\u09be\u0981\u09a1\u09bc\u09bf\u09af\u09bc\u09c7 \u09a5\u09be\u0995\u09be \u09aa\u09b0\u09cd\u09af\u099f\u0995\u09a6\u09c7\u09b0 \u09a6\u09b2\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.as7=new A.D(B.R,["Notice the winding trail and lush emerald tree canopy blanketing the valley slopes.","\u0989\u09aa\u09a4\u09cd\u09af\u0995\u09be\u09f0 \u09a2\u09be\u09b2\u09a4 \u09b8\u09c7\u0989\u099c\u09c0\u09af\u09bc\u09be \u0985\u09f0\u09a3\u09cd\u09af\u09f0 \u09a6\u09b2\u09bf\u099a\u09be \u0986\u09f0\u09c1 \u09b8\u09f0\u09cd\u09aa\u09bf\u09b2 \u09ac\u09be\u099f\u099f\u09cb \u09b2\u0995\u09cd\u09b7\u09cd\u09af \u0995\u09f0\u0995\u0964","\u092a\u0939\u093e\u0921\u093c \u0915\u0940 \u0922\u0932\u093e\u0928\u094b\u0902 \u0915\u094b \u0922\u0915\u0928\u0947 \u0935\u093e\u0932\u0947 \u0918\u0928\u0947 \u092a\u0928\u094d\u0928\u093e-\u0939\u0930\u0947 \u091c\u0902\u0917\u0932\u094b\u0902 \u0914\u0930 \u0930\u093e\u0938\u094d\u0924\u0947 \u0915\u094b \u0926\u0947\u0916\u0947\u0902\u0964","\u09aa\u09be\u09b9\u09be\u09a1\u09bc\u09c7\u09b0 \u09a2\u09be\u09b2 \u09ac\u09c7\u09af\u09bc\u09c7 \u09a8\u09c7\u09ae\u09c7 \u09af\u09be\u0993\u09af\u09bc\u09be \u09b8\u09ac\u09c1\u099c \u09ac\u09a8\u09be\u09a8\u09c0 \u0993 \u0986\u0981\u0995\u09be\u09ac\u09be\u0981\u0995\u09be \u09aa\u09a5\u099f\u09bf \u09a6\u09c7\u0996\u09c1\u09a8\u0964"],t.w)
B.asS=new A.D(B.R,["Find the roaring white waterfall thundering down into the lush rainforest pool.","\u0985\u09f0\u09a3\u09cd\u09af\u09f0 \u09ae\u09be\u099c\u09f0 \u099c\u09b2\u09be\u09b6\u09af\u09bc\u09a4 \u0997\u09f0\u099c\u09bf \u09a8\u09be\u09ae\u09bf \u0985\u09b9\u09be \u09b8\u09c1\u09ac\u09bf\u09b6\u09be\u09b2 \u09ac\u0997\u09be \u099c\u09b2\u09aa\u09cd\u09f0\u09aa\u09be\u09a4\u099f\u09cb \u09ac\u09bf\u099a\u09be\u09f0\u0995\u0964","\u091c\u0902\u0917\u0932 \u0915\u0947 \u092c\u0940\u091a \u0928\u0940\u091a\u0947 \u092c\u0928\u0947 \u0924\u093e\u0932 \u092e\u0947\u0902 \u0917\u0930\u091c\u0924\u0947 \u0939\u0941\u090f \u0917\u093f\u0930\u0924\u0947 \u0938\u092b\u0947\u0926 \u0935\u093f\u0936\u093e\u0932 \u091d\u0930\u0928\u0947 \u0915\u094b \u0916\u094b\u091c\u0947\u0902\u0964","\u09b8\u09ac\u09c1\u099c \u09ac\u09a8\u09c7\u09b0 \u09ae\u09be\u099d\u09c7 \u09b8\u09c3\u09b7\u09cd\u099f\u09bf \u09b9\u0993\u09af\u09bc\u09be \u099c\u09b2\u09be\u09b6\u09af\u09bc\u09c7 \u0997\u09b0\u09cd\u099c\u09a8 \u0995\u09b0\u09c7 \u0986\u099b\u09a1\u09bc\u09c7 \u09aa\u09a1\u09bc\u09be \u09ac\u09bf\u09b6\u09be\u09b2 \u09b6\u09c1\u09ad\u09cd\u09b0 \u099c\u09b2\u09aa\u09cd\u09b0\u09aa\u09be\u09a4\u099f\u09bf \u0996\u09c1\u0981\u099c\u09c1\u09a8\u0964"],t.w)
