B.aoH=new A.D(B.x,["Hi Grandpa! Hope you are having a wonderful day!","\u0928\u092e\u0938\u094d\u0924\u0947 \u0926\u093e\u0926\u093e\u091c\u0940! \u0906\u0936\u093e \u0939\u0948 \u0906\u092a\u0915\u093e \u0926\u093f\u0928 \u092c\u0939\u0941\u0924 \u0905\u091a\u094d\u091b\u093e \u092c\u0940\u0924 \u0930\u0939\u093e \u0939\u094b\u0917\u093e!","\u09b9\u09cd\u09af\u09be\u09b2\u09cb \u09a6\u09be\u09a6\u09c1! \u0986\u09b6\u09be \u0995\u09b0\u09bf \u0986\u09aa\u09a8\u09be\u09b0 \u09a6\u09bf\u09a8\u099f\u09bf \u0996\u09c1\u09ac \u09b8\u09c1\u09a8\u09cd\u09a6\u09b0 \u0995\u09be\u099f\u099b\u09c7!","\u09a8\u09ae\u09b8\u09cd\u0995\u09be\u09f0 \u0995\u0995\u09be! \u0986\u09b6\u09be \u0995\u09f0\u09cb\u0981 \u0986\u09aa\u09cb\u09a8\u09be\u09f0 \u09a6\u09bf\u09a8\u099f\u09cb \u0985\u09a4\u09bf \u09b8\u09c1\u09a8\u09cd\u09a6\u09f0\u0995\u09c8 \u09aa\u09be\u09f0 \u09b9\u09c8\u099b\u09c7!","\u0928\u092e\u0938\u094d\u0924\u0947 \u092c\u093e\u091c\u0947! \u0906\u0936\u093e \u091b \u0924\u092a\u093e\u0908\u0902\u0915\u094b \u0926\u093f\u0928 \u0927\u0947\u0930\u0948 \u0930\u093e\u092e\u094d\u0930\u094b \u092c\u093f\u0924\u093f\u0930\u0939\u0947\u0915\u094b \u091b!"],t.w)
B.aq2=new A.D(B.x,["Hello Dad, thinking of you today!","\u0928\u092e\u0938\u094d\u0924\u0947 \u092a\u093f\u0924\u093e\u091c\u0940, \u0906\u091c \u0906\u092a\u0915\u0940 \u092f\u093e\u0926 \u0906 \u0930\u0939\u0940 \u0925\u0940!","\u09b9\u09cd\u09af\u09be\u09b2\u09cb \u09ac\u09be\u09ac\u09be, \u0986\u099c \u09a4\u09cb\u09ae\u09be\u09b0 \u0995\u09a5\u09be \u09ad\u09be\u09ac\u099b\u09bf\u09b2\u09be\u09ae!","\u09a8\u09ae\u09b8\u09cd\u0995\u09be\u09f0 \u09a6\u09c7\u0989\u09a4\u09be, \u0986\u099c\u09bf \u0986\u09aa\u09cb\u09a8\u09be\u09f0 \u0995\u09a5\u09be \u09ad\u09be\u09ac\u09bf \u0986\u099b\u09bf\u09b2\u09cb\u0981!","\u0928\u092e\u0938\u094d\u0924\u0947 \u092c\u0941\u092c\u093e, \u0906\u091c \u0924\u092a\u093e\u0908\u0902\u0915\u094b \u0938\u092e\u094d\u091d\u0928\u093e \u0906\u0907\u0930\u0939\u0947\u0915\u094b \u091b!"],t.w)
B.apr=new A.D(B.x,["Hey Dad, looking forward to our weekend walk!","\u0905\u0930\u0947 \u092a\u093f\u0924\u093e\u091c\u0940, \u0939\u092e\u093e\u0930\u0947 \u0938\u092a\u094d\u0924\u093e\u0939\u093e\u0902\u0924 \u0915\u0940 \u0938\u0948\u0930 \u0915\u093e \u092c\u0947\u0938\u092c\u094d\u0930\u0940 \u0938\u0947 \u0907\u0902\u0924\u091c\u093c\u093e\u0930 \u0939\u0948!","\u0986\u09b0\u09c7 \u09ac\u09be\u09ac\u09be, \u0986\u09ae\u09be\u09a6\u09c7\u09b0 \u0989\u0987\u0995\u098f\u09a8\u09cd\u09a1\u09c7 \u09b9\u09be\u0981\u099f\u09be\u09b0 \u0985\u09aa\u09c7\u0995\u09cd\u09b7\u09be\u09af\u09bc \u09b0\u0987\u09b2\u09be\u09ae!","\u09a8\u09ae\u09b8\u09cd\u0995\u09be\u09f0 \u09a6\u09c7\u0989\u09a4\u09be, \u09b8\u09aa\u09cd\u09a4\u09be\u09b9\u09be\u09a8\u09cd\u09a4\u09f0 \u0996\u09cb\u099c \u0995\u09a2\u09bc\u09be\u09f0 \u09ac\u09be\u09ac\u09c7 \u0986\u0997\u09cd\u09f0\u09b9\u09c7\u09f0\u09c7 \u09ac\u09be\u099f \u099a\u09be\u0987 \u0986\u099b\u09cb\u0981!","\u0928\u092e\u0938\u094d\u0924\u0947 \u092c\u0941\u092c\u093e, \u0938\u092a\u094d\u0924\u093e\u0939\u0928\u094d\u0924\u0915\u094b \u092a\u0948\u0926\u0932 \u092f\u093e\u0924\u094d\u0930\u093e\u0915\u094b \u0909\u0924\u094d\u0938\u0941\u0915\u0924\u093e\u0915\u093e \u0938\u093e\u0925 \u092a\u0930\u094d\u0916\u093e\u0907\u092e\u093e \u091b\u0941!"],t.w)
B.aq1=new A.D(B.x,["Woof woof! Friendly tail wags!","\u092d\u094c\u0902\u0915-\u092d\u094c\u0902\u0915! \u092a\u094d\u092f\u093e\u0930 \u0938\u0947 \u092a\u0942\u0902\u091b \u0939\u093f\u0932\u093e\u0928\u093e!","\u0998\u09c7\u0989 \u0998\u09c7\u0989! \u09ad\u09be\u09b2\u09cb\u09ac\u09be\u09b8\u09be\u09af\u09bc \u09b2\u09c7\u099c \u09a8\u09be\u09a1\u09bc\u09be\u09a8\u09cb!","\u09ad\u09cc \u09ad\u09cc! \u09ae\u09f0\u09ae\u09c7\u09f0\u09c7 \u09a8\u09c7\u099c \u099c\u09cb\u0995\u09be\u09f0\u09bf\u099b\u09c7!","\u092d\u0941\u0915\u094d-\u092d\u0941\u0915\u094d! \u092e\u093e\u092f\u093e\u0932\u0941 \u092a\u0941\u091a\u094d\u091b\u0930 \u0939\u0932\u094d\u0932\u093e\u0907!"],t.w)
